INSERT INTO public.exams (id, title, exam_type, grade, stream, subject_id, time_limit_minutes, total_questions) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'ESSLCE Mathematics 2014 E.C. (Natural Science)', 'mock_full', 12, 'natural', 'math_g12', 180, 65) ON CONFLICT (id) DO UPDATE SET total_questions=EXCLUDED.total_questions;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('d1ab7835-34c4-582d-b613-2b28da2f0141', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the locus of all points in a plane for which the sum of the distances from two fixed points is constant?', 'በአንድ ጠለል ላይ ከሁለት ቋሚ ነጥቦች ያለው የርቀቶች ድምር ቋሚ የሆነባቸው ነጥቦች ስብስብ ምን ይባላል?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'd1ab7835-34c4-582d-b613-2b28da2f0141', 1) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('81091374-fd0d-5ba5-b5ea-d6d752295be9', 'd1ab7835-34c4-582d-b613-2b28da2f0141', 'A', 'Hyperbola', 'ሃይፐርቦላ', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4ab43b84-27ba-5c3c-a10c-7bd92fd429fc', 'd1ab7835-34c4-582d-b613-2b28da2f0141', 'B', 'Parabola', 'ፓራቦላ', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cd35e071-32ff-51b6-b77d-f0002a4e3b78', 'd1ab7835-34c4-582d-b613-2b28da2f0141', 'C', 'Ellipse', 'ኤሊፕስ', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('86619bfb-64df-5517-b3dc-a20fb6ecdd23', 'd1ab7835-34c4-582d-b613-2b28da2f0141', 'D', 'Circle', 'ክብ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('d5c0aff8-e4f9-5575-8d42-bf5f5eebd8cd', 'd1ab7835-34c4-582d-b613-2b28da2f0141', '1. An ellipse is defined as the locus of all points P in a plane where the sum of distances to two fixed foci F1 and F2 is constant: PF1 + PF2 = 2a.\n2. A hyperbola is the locus where the absolute difference of distances is constant (|PF1 - PF2| = 2a).\n3. A circle is the locus of points equidistant from a single fixed center.\n4. A parabola is the set of points equidistant from a fixed focus and a directrix line.\nTherefore, the correct answer is C (Ellipse).', 'Constant sum of distances from two fixed points = Ellipse.', 'Geometric definition of Ellipse: PF1 + PF2 = constant.', 'Confusing sum of distances (ellipse) with difference (hyperbola).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('69791aac-cf67-5560-b77d-fc6bd93ccdd2', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'The radian measure of an angle of 120° is equal to:', 'የ 120° አንግል የሬዲያን መለኪያ ከየትኛው ጋር እኩል ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 2) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('15f049ef-b8cd-5718-8d5a-fdb2c9aa23e5', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 'A', '2π/3', '2π/3', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1e904695-63f8-58f7-8763-7c38124ceb38', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 'B', '4π/3', '4π/3', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9d8285fd-b72f-5a4f-9ca6-a64d19cdbc77', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 'C', 'π/2', 'π/2', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e6455fbc-5430-54f5-a5b5-e3adf731cd83', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 'D', 'π/4', 'π/4', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('00860a4d-8786-5403-b300-537e5b02aa5f', '69791aac-cf67-5560-b77d-fc6bd93ccdd2', 'Convert degrees to radians by multiplying by π/180°:\nθ = 120° × (π / 180°) = 120π / 180 = 2π/3 radians.\nTherefore, the correct answer is A.', '120/180 reduces to 2/3, so 120° = 2π/3.', 'Radian conversion: radians = degrees × (π / 180°).', 'Inverting the conversion factor as 180/π.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the surface area of a sphere with radius 6 cm?', 'የራዲየሱ ርዝመት 6 ሳ.ሜ የሆነ ሉል አጠቃላይ የገጽታ ስፋት ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 3) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c8f3654f-eeb1-5b9e-a596-45d38b37b2b2', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 'A', '24π cm²', '24π ሳ.ሜ²', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('be94e8c0-c4a0-502b-8185-c585ae66700c', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 'B', '36π cm²', '36π ሳ.ሜ²', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e05225d7-f8e0-5b2e-83e0-0a6abbbacacc', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 'C', '48π cm²', '48π ሳ.ሜ²', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c268b06b-8fd0-5c9d-854b-1fdbc28ee93e', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', 'D', '144π cm²', '144π ሳ.ሜ²', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('1b319480-b660-5123-bc9d-73ca99e23300', '7b98d983-85d8-558f-b53e-1e2feb7a1fa8', '1. Surface area of a sphere formula: S = 4πr².\n2. With r = 6 cm:\nS = 4π(6²) = 4π(36) = 144π cm².\nTherefore, the correct answer is D.', 'S = 4 × π × 6² = 4 × 36 × π = 144π cm².', 'Surface area of sphere = 4πr².', 'Using circle area πr² = 36π instead of 4πr².') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b726f86b-6468-5aa2-80be-e082f7d5eafe', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which of the following is the measure of an exterior angle of a regular 10-sided polygon (decagon)?', 'ባለ 10 ጎን መደበኛ ፖሊጎን የአንድ ውጫዊ አንግል ልክ ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', 4) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('dbed1fa6-6969-52c7-b998-c4014e8e71a4', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', 'A', '72°', '72°', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('58865d73-c4de-5eec-a59a-149c1ff4b627', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', 'B', '144°', '144°', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b25b525c-e85b-59d0-af49-5eb1950b3814', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', 'C', '180°', '180°', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('292c0449-67ea-51e0-b333-53a807cc1577', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', 'D', '36°', '36°', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('94a59911-baea-5d65-a9a1-fe44fac7d3b3', 'b726f86b-6468-5aa2-80be-e082f7d5eafe', '1. The sum of all exterior angles for any convex polygon is 360°.\n2. For a regular decagon (n = 10 equal sides/angles):\nExterior angle = 360° / 10 = 36°.\nTherefore, the correct answer is D.', 'Exterior angle = 360° / n = 360° / 10 = 36°.', 'Exterior angle of regular n-gon = 360° / n.', 'Calculating the interior angle (180° - 36° = 144°).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'If the volume of a right circular cone is 64π cm³ and the diameter of its base is 8 cm, what is the height of the cone?', 'የአንድ ቀጥተኛ ክብ ሾጣጣ ይዘት 64π ሳ.ሜ³ እና የመሰረቱ ዲያሜትር 8 ሳ.ሜ ቢሆን፣ የሾጣጣው ቁመት ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 5) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d129fbd0-610d-5e4e-ac5a-b19e4b6892d5', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 'A', '4 cm', '4 ሳ.ሜ', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bed0d14d-dbb9-53ac-bdc4-29023af4c78e', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 'B', '12 cm', '12 ሳ.ሜ', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7d4bb223-d5a2-522b-8c1c-e28ec55750b7', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 'C', '8 cm', '8 ሳ.ሜ', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('53841b08-07b5-57c3-87fe-e92a682a4400', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', 'D', '3 cm', '3 ሳ.ሜ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('21251744-c90f-5f28-9c32-d74cb8f352d4', '00c1d4e6-dbe1-5ce5-8907-32c74e18b322', '1. Base radius r = diameter / 2 = 8 / 2 = 4 cm.\n2. Volume formula for a cone: V = (1/3)πr²h.\n3. Substitute values: 64π = (1/3)π(4)²h = (16/3)πh.\n4. Cancel π: 64 = 16h / 3 ⇒ 192 = 16h ⇒ h = 12 cm.\nTherefore, the correct answer is B.', '64π = (1/3)π(16)h ⇒ 64 = 16h/3 ⇒ h = 12 cm.', 'Cone volume V = 1/3 π r² h.', 'Using diameter 8 instead of radius 4.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('03dd91dd-f743-5188-bb63-0c05f278b9fd', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What are the quotient and remainder, respectively, when 75 is divided by 20?', '75 ለ 20 ሲካፈል ድርሻው እና ቀሪው በቅደም ተከተል ስንት ናቸው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 6) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('61e038e3-9faf-5512-b847-7c37ac1b6575', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 'A', '3 and 15', '3 እና 15', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8fb1cb53-3016-570f-89e2-d9395d812c85', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 'B', '4 and 5', '4 እና 5', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('70ac8732-7e4d-5334-9d16-6e78c577fff6', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 'C', '15 and 3', '15 እና 3', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ed94ffd1-f79a-589c-82fd-9d236db2b537', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 'D', '2 and 19', '2 እና 19', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('fb68e5a3-0481-5705-89e5-1d2be4d72e75', '03dd91dd-f743-5188-bb63-0c05f278b9fd', 'By the division algorithm:\n75 = 20(3) + 15, with 0 ≤ 15 < 20.\nTherefore, the quotient is 3 and the remainder is 15 (Choice A).', '75 / 20 = 3 with remainder 15 because 20 × 3 = 60 and 75 - 60 = 15.', 'Division Algorithm: a = bq + r where 0 ≤ r < b.', 'Reversing the order of quotient and remainder.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('fdd9743c-2005-547a-9558-618e3bd49937', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Given f(x) = x³ + px + 1, where f(0) and f(1) have opposite signs, which value of p can satisfy this condition?', 'f(x) = x³ + px + 1 ተሰጥቶ የ f(0) እና f(1) ዋጋዎች ተቃራኒ ምልክት ቢኖራቸው፣ የ p ዋጋ ከየትኞቹ አንዱ ሊሆን ይችላል?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'fdd9743c-2005-547a-9558-618e3bd49937', 7) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('85efb8e4-3a0f-53eb-831e-ccd95c6f25b4', 'fdd9743c-2005-547a-9558-618e3bd49937', 'A', '-1', '-1', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('19c2c948-c9ae-5115-8efe-935d804460a5', 'fdd9743c-2005-547a-9558-618e3bd49937', 'B', '-2', '-2', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2063ab96-e04e-57f4-bebc-0cb6b5f0b69d', 'fdd9743c-2005-547a-9558-618e3bd49937', 'C', '1', '1', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('749a6f32-0c54-5a30-8d9a-d25498aabdc7', 'fdd9743c-2005-547a-9558-618e3bd49937', 'D', '-3', '-3', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('0dee3a5e-d261-5b39-8623-60620e263a8a', 'fdd9743c-2005-547a-9558-618e3bd49937', '1. Compute f(0): f(0) = 0³ + p(0) + 1 = 1 > 0.\n2. For f(1) to have the opposite sign, f(1) must be strictly negative (f(1) < 0).\n3. Compute f(1): f(1) = 1³ + p(1) + 1 = p + 2.\n4. Set inequality: p + 2 < 0 ⇒ p < -2.\n5. Among the values, p = -3 is strictly less than -2 (which gives f(1) = -1 < 0).\nTherefore, the correct choice is D (-3).', 'f(0) = 1 (positive). For opposite signs, f(1) = p + 2 must be negative, so p < -2. Only p = -3 works.', 'Intermediate Value Theorem condition & function evaluation.', 'Choosing p = -2, which makes f(1) = 0 (zero has no sign, not opposite sign).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'In rolling a single fair six-sided die, what is the probability of obtaining a 3 or a 5?', 'አንድ መደበኛ ባለ 6 ጎን ዳይስ ሲወረወር 3 ወይም 5 የማግኘት እድል ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 8) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8dbf23a0-b562-57f0-933b-0f1251acaf0b', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 'A', '1/3', '1/3', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a41f58be-be76-52ee-b405-43a129ae87cd', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 'B', '1/4', '1/4', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('de7c1a5d-44fe-5fc1-8af6-8757ee4f3f8b', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 'C', '1/6', '1/6', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3e62f384-e876-5ac8-8bed-07a84187833e', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', 'D', '1/2', '1/2', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('32c85934-db3a-5115-97ae-7c0ed115fe50', '9aa03e6e-0bc9-5852-aab0-ca15bf5d32e5', '1. Sample space S = {1, 2, 3, 4, 5, 6}, total outcomes n(S) = 6.\n2. Favorable outcomes E = {3, 5}, n(E) = 2.\n3. Probability P(E) = n(E) / n(S) = 2/6 = 1/3.\nTherefore, the correct answer is A.', '2 favorable outcomes out of 6 total = 2/6 = 1/3.', 'Theoretical Probability: P(E) = favorable outcomes / total outcomes.', 'Multiplying probabilities (1/6 × 1/6) instead of adding mutually exclusive events (1/6 + 1/6).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b871e478-d7cd-5937-ba2a-917ce6c13f79', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'Which one of the following statements is true regarding inverse trigonometric functions?', 'ስለ ግልባጭ ትሪጎኖሜትሪክ ፈንክሽኖች ከሚከተሉት ውስጥ እውነት የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', 9) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('952990cf-b74e-5588-9379-12476ead08d3', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', 'A', 'The range of arctan(x) is [-π, π]', 'የ arctan(x) ሬንጅ [-π, π] ነው', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('fc733017-cb7d-58ee-b0a4-0633dfdc43e3', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', 'B', 'The range of arcsin(x) is (-∞, ∞)', 'የ arcsin(x) ሬንጅ (-∞, ∞) ነው', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('20b12ab6-e23e-541d-8177-61e513c1ce57', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', 'C', 'The domain of arccos(x) is [-1, 1]', 'የ arccos(x) ዶሜን [-1, 1] ነው', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('324e2bf1-2306-5aca-9949-dd307a5e6e80', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', 'D', 'The domain of arcsin(x) is [0, π]', 'የ arcsin(x) ዶሜን [0, π] ነው', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('2fde6e69-c2e2-530a-a002-1184e4659647', 'b871e478-d7cd-5937-ba2a-917ce6c13f79', '1. Since -1 ≤ cos(θ) ≤ 1 for all real θ, the domain of arccos(x) is the interval [-1, 1]. Range is [0, π].\n2. The domain of arcsin(x) is [-1, 1], and its range is [-π/2, π/2].\n3. The domain of arctan(x) is (-∞, ∞), and its range is (-π/2, π/2).\nTherefore, statement C is the only true statement.', 'Cosine outputs between -1 and 1, so inverse cosine accepts inputs in [-1, 1].', 'Domains and ranges of inverse trigonometric functions.', 'Confusing the range of cos(x) with the range of arccos(x).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'The angle of depression of the top of a flagpole from the top of a building is 30°. The horizontal distance between the building and the pole is 40√3 m, and the pole is 10 m high. What is the height of the building?', 'ከአንድ ህንጻ ጫፍ ወደ ባንዲራ መስቀያ ጫፍ ያለው የቁልቁለት አንግል 30° ነው። በህንጻው እና በባንዲራው መካከል ያለው አግድም ርቀት 40√3 ሜትር ሲሆን፣ የባንዲራው ርዝመት 10 ሜትር ነው። የህንጻው ቁመት ስንት ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 10) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7011d28f-4196-5763-a960-a79f10c0e352', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 'A', '20√3 m', '20√3 ሜ', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('930d70a9-c7ef-5c4f-81f4-6c47feecf49a', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 'B', '10(4/√3 + 1) m', '10(4/√3 + 1) ሜ', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d896b0af-6608-5312-8283-3026b1f38729', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 'C', '50 m', '50 ሜ', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7202ef64-a621-5765-ac5c-bd4a22ebba84', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', 'D', '40 m', '40 ሜ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('00a74677-4e8b-5f9b-98b4-788922943e8e', '2960dc0d-3bd0-5f4e-8c74-082fa10c31f4', '1. Let H be the total height of the building.\n2. The top of the flagpole is at height 10 m, so the vertical difference is Δy = H - 10.\n3. The horizontal distance d = 40√3 m.\n4. Using trigonometry for angle of depression 30°:\ntan(30°) = (H - 10) / (40√3).\n5. Since tan(30°) = 1/√3:\n1/√3 = (H - 10) / (40√3) ⇒ H - 10 = 40 ⇒ H = 50 m.\nTherefore, the correct answer is C (50 m).', 'tan(30°) = 1/√3 = (H - 10)/(40√3) ⇒ H - 10 = 40 ⇒ H = 50 m.', 'Angle of depression in right triangle trigonometry: tan(θ) = opposite / adjacent.', 'Forgetting to add the 10 m flagpole height to the vertical difference.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('567d5944-3fea-5caa-b311-b796a977fc9b', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Let R = {(x, y) : y ≥ x² + 1 and y ≤ 5}. Which relation defines the inverse relation R⁻¹?', 'R = {(x, y) : y ≥ x² + 1 and y ≤ 5} ቢሆን፣ የግልባጭ ዝምድናውን R⁻¹ የሚገልጸው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '567d5944-3fea-5caa-b311-b796a977fc9b', 11) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ad41dbef-877b-5716-8270-4b15edf2759b', '567d5944-3fea-5caa-b311-b796a977fc9b', 'A', '{(x, y) : x ≥ y² + 1 and x ≤ 5}', '{(x, y) : x ≥ y² + 1 and x ≤ 5}', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0f9f253c-f43a-5b53-88c2-7ed1d5397d7f', '567d5944-3fea-5caa-b311-b796a977fc9b', 'B', '{(x, y) : x ≤ y² + 1 and x ≤ 5}', '{(x, y) : x ≤ y² + 1 and x ≤ 5}', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('04345b7d-e5bd-587b-b138-9c34ab1f1a59', '567d5944-3fea-5caa-b311-b796a977fc9b', 'C', '{(x, y) : x ≥ y² - 1 and x ≤ 5}', '{(x, y) : x ≥ y² - 1 and x ≤ 5}', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('63ba10f2-c764-510c-a5b8-38abdf1f0c7e', '567d5944-3fea-5caa-b311-b796a977fc9b', 'D', '{(x, y) : x ≤ y² - 1 and x ≤ 5}', '{(x, y) : x ≤ y² - 1 and x ≤ 5}', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('da4e8adf-9f9a-5676-a67d-54817867b9c1', '567d5944-3fea-5caa-b311-b796a977fc9b', '1. The inverse relation R⁻¹ of any relation R on ℝ is obtained by interchanging the variables x and y in its defining conditions.\n2. In R: y ≥ x² + 1 becomes x ≥ y² + 1 in R⁻¹.\n3. In R: y ≤ 5 becomes x ≤ 5 in R⁻¹.\n4. Therefore: R⁻¹ = {(x, y) : x ≥ y² + 1 and x ≤ 5}.\nTherefore, the correct answer is A.', 'Swap x and y in all inequalities: y ≥ x² + 1 becomes x ≥ y² + 1, and y ≤ 5 becomes x ≤ 5.', 'Inverse of a relation R: R⁻¹ = {(y, x) : (x, y) ∈ R}.', 'Attempting algebraic subtraction instead of simply swapping coordinates x and y.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Given matrices A = [2 0 5; 3 1 4; 0 6 -2] and B = [1 3 0; 6 5 2; 9 7 0], which matrix represents A - B?', 'ማትሪክስ A = [2 0 5; 3 1 4; 0 6 -2] እና B = [1 3 0; 6 5 2; 9 7 0] ቢሆኑ፣ A - B የሚሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 12) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('da54c3a7-05b7-56da-bea1-54ca2196fcbd', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 'A', '[1 3 5; -3 -4 2; 9 1 2]', '[1 3 5; -3 -4 2; 9 1 2]', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('634b28ca-5746-5c93-b2d9-1d592239d6a4', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 'B', '[1 -3 -5; -3 -4 2; 9 1 2]', '[1 -3 -5; -3 -4 2; 9 1 2]', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ded85be6-2e18-57fb-afcb-46af9773849c', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 'C', '[1 3 5; -3 -4 -2; -9 1 2]', '[1 3 5; -3 -4 -2; -9 1 2]', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('99da1698-a9a6-5f85-b54a-a95a517368ab', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 'D', '[1 -3 5; -3 -4 2; -9 -1 -2]', '[1 -3 5; -3 -4 2; -9 -1 -2]', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('e7ccedea-7488-558c-a1e8-a5204ce6be7f', '4e3379e1-3422-55a9-9004-2f3bf9a87d0c', 'Subtract corresponding entries (A - B)ij = Aij - Bij:\nRow 1: [2-1, 0-3, 5-0] = [1, -3, 5]\nRow 2: [3-6, 1-5, 4-2] = [-3, -4, 2]\nRow 3: [0-9, 6-7, -2-0] = [-9, -1, -2]\nCombining these rows yields: [1 -3 5; -3 -4 2; -9 -1 -2].\nTherefore, the correct answer is D.', 'Subtract each element: Row 1 is (1, -3, 5), Row 2 is (-3, -4, 2), Row 3 is (-9, -1, -2).', 'Matrix subtraction element by element.', 'Sign errors when subtracting negative numbers or zero.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('6ce0b4c8-ab07-53c9-837a-7bd916d37550', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Starting at the origin (0, 0, 0), move 5 units along the negative x-axis, 5 units along the positive y-axis, and 5 units along the negative z-axis. What are the coordinates of the final point?', 'ከመነሻ ነጥብ (0, 0, 0) በመነሳት፣ 5 ዩኒት በአሉታዊ x-ዘንግ፣ 5 ዩኒት በአዎንታዊ y-ዘንግ፣ እና 5 ዩኒት በአሉታዊ z-ዘንግ ቢጓዝ የመጨረሻው ነጥብ ኮኦርዲኔት ስንት ይሆናል?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', 13) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('5482a0a7-2abe-5ed3-bfc7-c5a39f7c6711', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', 'A', '(5, 5, 5)', '(5, 5, 5)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d0301f1a-fe55-5700-992b-7a00f7e21c57', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', 'B', '(-5, 5, -5)', '(-5, 5, -5)', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('785c02c0-9bfb-5e7e-a0ba-9c18d7f1b1db', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', 'C', '(5, -5, -5)', '(5, -5, -5)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('42fa1427-f9c9-550a-bf13-c3c5d8363c9a', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', 'D', '(-5, -5, 5)', '(-5, -5, 5)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('46ef7cea-b122-538d-96dd-278a4485bdd6', '6ce0b4c8-ab07-53c9-837a-7bd916d37550', '1. Negative x-axis motion by 5: x = 0 - 5 = -5.\n2. Positive y-axis motion by 5: y = 0 + 5 = 5.\n3. Negative z-axis motion by 5: z = 0 - 5 = -5.\n4. Resulting coordinate is (-5, 5, -5).\nTherefore, the correct answer is B.', '(-5 in x, +5 in y, -5 in z) = (-5, 5, -5).', '3D Cartesian coordinate system.', 'Mixing signs for positive vs negative directions.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('05c4ad0b-cf7b-522e-8ade-42d53781d542', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which one of the following physical quantities is a vector quantity?', 'ከሚከተሉት መጠኖች ውስጥ ቬክተር የሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '05c4ad0b-cf7b-522e-8ade-42d53781d542', 14) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b5fb6de1-219c-52c5-9bb1-59f77afd9f3f', '05c4ad0b-cf7b-522e-8ade-42d53781d542', 'A', 'Weight of an object', 'የአንድ አካል ክብደት (Weight)', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('67276783-2c36-5e3c-98de-9d2e6b9355f0', '05c4ad0b-cf7b-522e-8ade-42d53781d542', 'B', 'Speed of a motorbike', 'የሞተር ሳይክል ፍጥነት (Speed)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2014223a-4d67-5984-8797-85c1634dd02e', '05c4ad0b-cf7b-522e-8ade-42d53781d542', 'C', 'Volume of a box', 'የሳጥን ይዘት (Volume)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('68943571-ce2e-52f0-abd8-afa02caec05d', '05c4ad0b-cf7b-522e-8ade-42d53781d542', 'D', 'Width of a bedroom', 'የመኝታ ክፍል ወርድ (Width)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('b4962b5c-307c-5ff5-90e3-b0791f58274b', '05c4ad0b-cf7b-522e-8ade-42d53781d542', '1. A vector quantity possesses both magnitude and directional orientation.\n2. Weight is gravitational force (W = mg), which has magnitude and points downward toward Earth''s center of mass.\n3. Speed, volume, and width have only magnitude (scalars).\nTherefore, the correct answer is A (Weight).', 'Weight is a force with direction (downward) = Vector.', 'Vectors vs Scalars: Vectors have magnitude and direction.', 'Confusing mass (scalar) with weight (vector force).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Which one of the following is the first derivative f''(x) of the function f(x) = tan(x) + 3ˣ?', 'የፈንክሽን f(x) = tan(x) + 3ˣ የመጀመሪያ ዲሪቬቲቭ f''(x) የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 15) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9c1c47ec-8251-56cc-9d63-d639b6711723', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 'A', 'sec²(x) + 3ˣ ln(3)', 'sec²(x) + 3ˣ ln(3)', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('10bb0905-05bb-516e-a3ac-99bc675acb08', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 'B', '-csc²(x) + 3ˣ ln(3)', '-csc²(x) + 3ˣ ln(3)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9f332fd9-047e-52de-be04-24db7da65615', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 'C', '-tan(x) + 3ˣ ln(3)', '-tan(x) + 3ˣ ln(3)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e38fce3c-8d9b-5368-95c9-dccb3ae30c41', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', 'D', 'sec²(x) + 3ˣ', 'sec²(x) + 3ˣ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('e6ec1da0-2022-5cb0-99ec-40a0044d2051', 'b3fe568a-c04b-5617-9a4c-fdc2f62efcbc', '1. Differentiate term by term:\n- d/dx [tan(x)] = sec²(x)\n- d/dx [aˣ] = aˣ ln(a), so d/dx [3ˣ] = 3ˣ ln(3)\n2. Adding the derivatives: f''(x) = sec²(x) + 3ˣ ln(3).\nTherefore, the correct answer is A.', 'Derivative of tan(x) is sec²(x), and derivative of 3ˣ is 3ˣ ln(3).', 'Derivatives of trigonometric and exponential functions: d/dx(aˣ) = aˣ ln(a).', 'Forgetting the ln(3) factor when differentiating 3ˣ.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('4b7e4d0e-fb51-5b97-add9-b66129cbd189', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which point lies inside the sphere x² + y² + z² = 5?', 'በሉል x² + y² + z² = 5 ውስጥ የሚገኘው ነጥብ የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 16) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('37d6a361-7350-5e42-9157-b02b42ebfa3b', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 'A', '(1, -2, 2)', '(1, -2, 2)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7d791fcc-0580-5fbd-bcc5-afa43e65338a', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 'B', '(1, 1, 1)', '(1, 1, 1)', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9ddc391f-a372-504d-9cee-3339298dc84f', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 'C', '(1, 2, 3)', '(1, 2, 3)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a2f73884-1c6b-5c64-acba-03d4747de617', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 'D', '(0, -2, 3)', '(0, -2, 3)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('d71d1723-5553-5d07-8564-bde4cd73256f', '4b7e4d0e-fb51-5b97-add9-b66129cbd189', 'A point (x, y, z) lies strictly inside the sphere centered at the origin of radius √5 when x² + y² + z² < 5.\n- For (1, -2, 2): 1² + (-2)² + 2² = 1 + 4 + 4 = 9 > 5 (outside)\n- For (1, 1, 1): 1² + 1² + 1² = 1 + 1 + 1 = 3 < 5 (inside)\n- For (1, 2, 3): 1 + 4 + 9 = 14 > 5 (outside)\n- For (0, -2, 3): 0 + 4 + 9 = 13 > 5 (outside)\nTherefore, the point inside is B (1, 1, 1).', '1² + 1² + 1² = 3, which is less than 5, so (1, 1, 1) is inside the sphere.', 'Equation of a sphere: Interior region is x² + y² + z² < r².', 'Testing against √5 instead of 5 (r²).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which one of the following gives the trigonometric (polar) form of the complex number z = 2 - 2√3 i?', 'የኮምፕሌክስ ቁጥር z = 2 - 2√3 i ትሪጎኖሜትሪክ (ፖላር) ፎርም የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 17) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('53e00d9b-ef28-5924-bbdf-201a82ffd1e9', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 'A', '4(cos(5π/3) + i sin(5π/3))', '4(cos(5π/3) + i sin(5π/3))', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f03534fd-e433-50ff-9aa1-358f57f64afe', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 'B', '4(cos(4π/3) + i sin(4π/3))', '4(cos(4π/3) + i sin(4π/3))', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('73b03bfc-94aa-5f03-a448-b0154e1b2e74', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 'C', '4(cos(3π/4) + i sin(3π/4))', '4(cos(3π/4) + i sin(3π/4))', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b912a97c-0df0-5cd7-ac28-fe7cc9be3442', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', 'D', '4(cos(π/3) + i sin(π/3))', '4(cos(π/3) + i sin(π/3))', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('cb7c7799-dc52-5c7d-9003-ef867335e45e', '67f80349-57ea-5a0e-8aa3-60a735f1fb9a', '1. Modulus: r = √(x² + y²) = √(2² + (-2√3)²) = √(4 + 12) = √16 = 4.\n2. Argument: Since x = 2 > 0 and y = -2√3 < 0, z is in Quadrant IV.\n3. Reference angle θ_ref = arctan(|-2√3| / 2) = arctan(√3) = π/3 (or 60°).\n4. In Quadrant IV: θ = 2π - π/3 = 5π/3 (or 300°).\n5. Polar form: z = r(cos θ + i sin θ) = 4(cos(5π/3) + i sin(5π/3)).\nTherefore, the correct answer is A.', 'r = √(4+12) = 4. Angle in Q4 with tan θ = -√3 is 5π/3. Form is 4(cos(5π/3) + i sin(5π/3)).', 'Polar form of complex numbers: z = r(cos θ + i sin θ).', 'Choosing an argument in Quadrant II (2π/3) instead of Quadrant IV (5π/3).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('deddab48-9dce-50db-a6cc-1e34c04d58c8', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'If vector a = (4, 3, 2) and vector b = (1, 2, -3), which vector statement is NOT correct?', 'ቬክተር a = (4, 3, 2) እና b = (1, 2, -3) ቢሆኑ፣ ትክክል ያልሆነው አረፍተ ነገር የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 18) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('44dd8d2a-b38f-59e9-bf6e-73b4e8f7db01', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 'A', 'a + b = (5, 5, -1)', 'a + b = (5, 5, -1)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2a6ef83a-170a-5736-8f19-50b65911b9e1', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 'B', 'a + 2b = (6, 7, -4)', 'a + 2b = (6, 7, -4)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cbe0de58-1070-55c7-8a0c-bd6eb6d4e2cf', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 'C', 'b - a = (-3, -1, -5)', 'b - a = (-3, -1, -5)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('382deb0f-9cfa-5c34-8312-eda8a6b3ae42', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 'D', 'a - 2b = (2, 1, 8)', 'a - 2b = (2, 1, 8)', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('7e83ade4-9ec5-5db4-8b5b-f556ffa3711b', 'deddab48-9dce-50db-a6cc-1e34c04d58c8', 'Compute each operation:\n- a + b = (4+1, 3+2, 2-3) = (5, 5, -1) (Correct)\n- a + 2b = (4+2, 3+4, 2-6) = (6, 7, -4) (Correct)\n- b - a = (1-4, 2-3, -3-2) = (-3, -1, -5) (Correct)\n- a - 2b = (4 - 2(1), 3 - 2(2), 2 - 2(-3)) = (4-2, 3-4, 2+6) = (2, -1, 8).\nChoice D gives (2, 1, 8) with the middle component +1 instead of -1, so statement D is incorrect.\nTherefore, the answer is D.', 'a - 2b = (4-2, 3-4, 2+6) = (2, -1, 8). Statement D says (2, 1, 8), which is false.', 'Linear combinations of vectors in ℝ³.', 'Sign error in subtracting 2(2) from 3: 3 - 4 = -1, not +1.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('310b931d-5ca0-53c8-a53e-5604bfee9942', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the product of the complex numbers z = 2 - 3i and w = 5 + 2i?', 'የኮምፕሌክስ ቁጥሮች z = 2 - 3i እና w = 5 + 2i ብዜት ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '310b931d-5ca0-53c8-a53e-5604bfee9942', 19) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('766d568a-d977-5a7d-be13-bb7786b20843', '310b931d-5ca0-53c8-a53e-5604bfee9942', 'A', '16 + 11i', '16 + 11i', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('22e54a2e-a3d6-503c-b4d0-08fe97b12851', '310b931d-5ca0-53c8-a53e-5604bfee9942', 'B', '4 - 11i', '4 - 11i', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ca2f8d36-71d2-5354-a26c-916f6a6f52f0', '310b931d-5ca0-53c8-a53e-5604bfee9942', 'C', '16 - 11i', '16 - 11i', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2b0c8d27-79f6-5db4-a834-4cfe4ec44fa0', '310b931d-5ca0-53c8-a53e-5604bfee9942', 'D', '29', '29', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('6095b84c-a984-5997-969a-098e0476b662', '310b931d-5ca0-53c8-a53e-5604bfee9942', 'Use the distributive property (FOIL):\n(2 - 3i)(5 + 2i) = 2(5) + 2(2i) - 3i(5) - 3i(2i)\n= 10 + 4i - 15i - 6i².\nSince i² = -1:\n-6i² = -6(-1) = +6.\nCombining real and imaginary parts:\n(10 + 6) + (4 - 15)i = 16 - 11i.\nTherefore, the correct answer is C.', '(2-3i)(5+2i) = 10 + 4i - 15i - 6(-1) = 16 - 11i.', 'Complex number multiplication using i² = -1.', 'Treating -6i² as -6 instead of +6.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which statement is true regarding the arithmetic mean of a data set?', 'ስለ አንድ የዳታ ስብስብ አርቲሜቲክ ሚን እውነት የሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 20) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c181c2cc-812c-5727-899a-338b517fed77', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 'A', 'It is affected by extreme values (outliers)', 'በጣም ትላልቅ ወይም ትናንሽ ቁጥሮች ተጽዕኖ ይደርስበታል', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e54ec161-8aca-5310-b822-9cb7f98dfa06', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 'B', 'There can be two means for the same data set', 'ለአንድ ዳታ ሁለት ሚኖች ሊኖሩ ይችላሉ', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1c95da09-ecef-5121-92d9-2733ef5a3004', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 'C', 'It can be used directly for qualitative data', 'ለጥራት መረጃ በቀጥታ ይሰላል', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('03679a1a-33ce-571c-8b48-b0f17f510455', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', 'D', 'It can always be found when some values are missing', 'የጎደሉ ቁጥሮች ቢኖሩም ሁልጊዜ ማግኘት ይቻላል', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('79342855-0472-5ba7-9a02-6755ea1186a7', '7adad33f-fc31-5fa6-b6c3-e9c618a34c99', '1. The arithmetic mean (x̄ = Σx / n) incorporates every single numerical observation in its sum.\n2. Consequently, extreme high or low values (outliers) disproportionately shift the mean.\n3. The mean is always uniquely defined (cannot have two means), applies only to quantitative data, and requires all values.\nTherefore, the correct answer is A.', 'The mean uses all values, so high or low outliers pull the average up or down.', 'Properties of measures of central tendency (Mean vs Median).', 'Confusing the mean with the mode (which can have multiple values / bimodal).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b8aab63b-8d6f-576d-b1c8-39042c219208', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'In △ABC, side lengths are AB = 10, BC = 14, and AC = 8. What is the area of the triangle?', 'በሦስት ማዕዘን △ABC ውስጥ የጎኖቹ ርዝመት AB = 10፣ BC = 14፣ እና AC = 8 ቢሆን፣ የሦስት ማዕዘኑ ስፋት ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b8aab63b-8d6f-576d-b1c8-39042c219208', 21) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9f14c2d2-2ea5-5e8e-98f2-1d163a814c9a', 'b8aab63b-8d6f-576d-b1c8-39042c219208', 'A', '10√6 square units', '10√6 ስኩዌር ዩኒት', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('6b7959f8-9425-5256-8e5f-050a3cb22072', 'b8aab63b-8d6f-576d-b1c8-39042c219208', 'B', '16√6 square units', '16√6 ስኩዌር ዩኒት', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7d702e1d-37ab-506d-9543-35c27a49df42', 'b8aab63b-8d6f-576d-b1c8-39042c219208', 'C', '16√3 square units', '16√3 ስኩዌር ዩኒት', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('277d5b9f-8333-5aae-8f8d-73c1f365d519', 'b8aab63b-8d6f-576d-b1c8-39042c219208', 'D', '16√2 square units', '16√2 ስኩዌር ዩኒት', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('33cf3f45-a5e9-5634-be42-7527bec7b6f1', 'b8aab63b-8d6f-576d-b1c8-39042c219208', '1. Use Heron''s formula: Area = √(s(s-a)(s-b)(s-c)).\n2. Semiperimeter s = (10 + 14 + 8) / 2 = 32 / 2 = 16.\n3. Compute differences:\n- s - a = 16 - 10 = 6\n- s - b = 16 - 14 = 2\n- s - c = 16 - 8 = 8\n4. Area = √(16 × 6 × 2 × 8) = √(1536) = √(256 × 6) = 16√6.\nTherefore, the correct answer is B.', 'Semiperimeter s = 16. Area = √(16 × 6 × 2 × 8) = √1536 = 16√6.', 'Heron''s Formula for triangle area: A = √(s(s-a)(s-b)(s-c)).', 'Arithmetic error under the square root when multiplying factors.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('6a506191-1c23-5c2c-8845-46a247ecc02e', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Evaluate the indefinite integral: ∫ (1/√x - e⁻³ˣ + 5/x²) dx', 'የኢንቴግራል ስሌቱን ዋጋ ፈልጉ: ∫ (1/√x - e⁻³ˣ + 5/x²) dx', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '6a506191-1c23-5c2c-8845-46a247ecc02e', 22) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('995f90cf-360e-5b65-b87f-f872290ccfb3', '6a506191-1c23-5c2c-8845-46a247ecc02e', 'A', '2√x + e⁻³ˣ/3 + 5/x + C', '2√x + e⁻³ˣ/3 + 5/x + C', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7c9eab8f-b125-5e30-b4bb-1ba06d422874', '6a506191-1c23-5c2c-8845-46a247ecc02e', 'B', '2√x + e⁻³ˣ/3 - 5/x + C', '2√x + e⁻³ˣ/3 - 5/x + C', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('fbd50bf6-a6d0-5be1-a186-1957cacd5cda', '6a506191-1c23-5c2c-8845-46a247ecc02e', 'C', '2√x - e⁻³ˣ/3 - 5/x + C', '2√x - e⁻³ˣ/3 - 5/x + C', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('6e587302-d59f-55eb-b528-a618e0033039', '6a506191-1c23-5c2c-8845-46a247ecc02e', 'D', '2√x - e⁻³ˣ/3 + 5/x + C', '2√x - e⁻³ˣ/3 + 5/x + C', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('71380783-97da-52fc-8eb6-a61723bb86f8', '6a506191-1c23-5c2c-8845-46a247ecc02e', 'Integrate term by term:\n1. ∫ x^(-1/2) dx = x^(1/2) / (1/2) = 2√x\n2. ∫ -e^(-3x) dx = - (e^(-3x) / -3) = + (1/3)e^(-3x)\n3. ∫ 5x^(-2) dx = 5 (x^(-1) / -1) = - 5/x\nCombining terms with constant of integration C:\n∫ (1/√x - e⁻³ˣ + 5/x²) dx = 2√x + e⁻³ˣ/3 - 5/x + C.\nTherefore, the correct answer is B.', '∫x^(-1/2) = 2√x, ∫-e^(-3x) = +e^(-3x)/3, ∫5x^(-2) = -5/x.', 'Basic power rule & exponential integration formulas.', 'Negative sign error when dividing by -3 during exponential integration.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'A shaded relation on a coordinate plane has an upper horizontal boundary at y = 6 extending downwards, and a right vertical boundary at x = 2 extending to the left. Which pair represents its domain and range?', 'በኮኦርዲኔት ጠለል ላይ የቀረበ ዝምድና ቀኝ ወሰኑ x = 2 ወደ ግራ እና የላይኛው ወሰኑ y = 6 ወደ ታች ቢሆን፣ ዶሜኑ እና ሬንጁ የትኛው ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 23) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2b5447f1-78f7-53a7-990f-20945d1e6d7a', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 'A', '{x : x ≤ 2} and {y : y ≤ 6}', '{x : x ≤ 2} እና {y : y ≤ 6}', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e6283b93-a90f-5495-b263-4fea34cea0df', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 'B', '{x : x ≤ 2} and ℝ', '{x : x ≤ 2} እና ℝ', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8b523487-8815-5f25-92b1-8747ba37c190', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 'C', 'ℝ and {y : y ≤ 2}', 'ℝ እና {y : y ≤ 2}', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4472a104-cdb7-552c-8000-bb6547c751b5', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', 'D', 'ℝ and ℝ', 'ℝ እና ℝ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('4c0660d8-ff59-53f3-84dd-7d12e835b91b', '80c7da17-1fc4-5b7d-b15e-12e28e0b0329', '1. Domain (x-values): The region extends indefinitely to the left with maximum x = 2, so Domain = (-∞, 2] = {x : x ≤ 2}.\n2. Range (y-values): The region extends indefinitely downward with maximum y = 6, so Range = (-∞, 6] = {y : y ≤ 6}.\nTherefore, the correct answer is A.', 'x values go up to 2 (x ≤ 2); y values go up to 6 (y ≤ 6).', 'Graph-based domain and range extraction.', 'Swapping the domain and range boundaries.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('34b71525-a123-56da-87ab-8b4f722c4820', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Let f be a continuous function on [a, b]. Which property of definite integrals is NOT true?', 'ፈንክሽን f በ [a, b] ላይ ቀጣይ ቢሆን፣ ከሚከተሉት የዴፊኒት ኢንቴግራል ህጎች ውስጥ ትክክል ያልሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '34b71525-a123-56da-87ab-8b4f722c4820', 24) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('653ad676-db75-5322-8394-6479272d1f08', '34b71525-a123-56da-87ab-8b4f722c4820', 'A', '∫ₐᵇ f(x) dx = - ∫ᵦᵃ f(x) dx', '∫ₐᵇ f(x) dx = - ∫ᵦᵃ f(x) dx', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('95376464-6dea-5e46-9780-ed290bac2b29', '34b71525-a123-56da-87ab-8b4f722c4820', 'B', '∫ₐᵇ k f(x) dx = k ∫ₐᵇ f(x) dx', '∫ₐᵇ k f(x) dx = k ∫ₐᵇ f(x) dx', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1367f663-ba22-52be-9a07-b374468fb36a', '34b71525-a123-56da-87ab-8b4f722c4820', 'C', '∫ₐᵇ f(x) dx = ∫ₐᶜ f(x) dx - ∫꜀ᵇ f(x) dx', '∫ₐᵇ f(x) dx = ∫ₐᶜ f(x) dx - ∫꜀ᵇ f(x) dx', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bec380f9-bcf6-548c-a9b5-b4d724c84d90', '34b71525-a123-56da-87ab-8b4f722c4820', 'D', '∫꜀ᶜ f(x) dx = 0', '∫꜀ᶜ f(x) dx = 0', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('e034e510-3e55-55d6-93a1-6c78106ece4b', '34b71525-a123-56da-87ab-8b4f722c4820', '1. The interval addition property of definite integrals states: ∫ₐᵇ f(x) dx = ∫ₐᶜ f(x) dx + ∫꜀ᵇ f(x) dx.\n2. Choice C has a subtraction sign instead of an addition sign, making it mathematically false.\n3. Choices A, B, and D are standard correct integral properties.\nTherefore, the correct answer is C.', 'Integral from a to b is the SUM of integrals (a to c + c to b), not the difference.', 'Fundamental linearity and interval properties of definite integrals.', 'Confusing interval addition with reversal of limits.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Evaluate the definite integral: ∫₀¹ x eˣ dx', 'የዴፊኒት ኢንቴግራል ስሌቱን ዋጋ ፈልጉ: ∫₀¹ x eˣ dx', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 25) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('83477a81-57f9-5d58-895d-cb02a736467c', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 'A', 'e', 'e', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('11a2a368-fb6d-5ef5-8ac6-73e55434a040', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 'B', '-e', '-e', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0a3e4ae3-6785-510f-a7e6-978e90557b5b', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 'C', '-1', '-1', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('59bc72c1-be99-5238-8081-d4ce786e9291', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', 'D', '1', '1', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('f1cf7040-f39b-5b81-9be5-1455ea949b0f', '5b8cd397-9cfd-5d1d-bb78-e30322d6173f', '1. Use integration by parts: ∫ u dv = uv - ∫ v du.\n- Let u = x ⇒ du = dx\n- Let dv = eˣ dx ⇒ v = eˣ\n2. Indefinite integral: ∫ x eˣ dx = x eˣ - ∫ eˣ dx = x eˣ - eˣ = eˣ(x - 1).\n3. Evaluate from 0 to 1:\n[e¹(1 - 1)] - [e⁰(0 - 1)] = [e(0)] - [1(-1)] = 0 - (-1) = 1.\nTherefore, the correct answer is D.', 'Integral is eˣ(x - 1). At x = 1: 0. At x = 0: -1. Top minus bottom: 0 - (-1) = 1.', 'Integration by parts formula with limits: [uv]ₐᵇ - ∫ₐᵇ v du.', 'Forgetting that e⁰ = 1 when evaluating the lower limit.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b7968511-077a-5c42-9751-65be9867b2ab', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Simplify the radical expression: (6√20 - 3√45) / (3√75)', 'የራዲካል ስሌቱን አቃልሉ: (6√20 - 3√45) / (3√75)', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b7968511-077a-5c42-9751-65be9867b2ab', 26) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('71f93019-8c0c-57f4-baf6-b4c710aad55d', 'b7968511-077a-5c42-9751-65be9867b2ab', 'A', '√3', '√3', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('850b3916-8cef-5419-95d3-81e745a7f9ca', 'b7968511-077a-5c42-9751-65be9867b2ab', 'B', '√15 / 15', '√15 / 15', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0e10a318-101f-5b39-9a8b-6ab784ecdce2', 'b7968511-077a-5c42-9751-65be9867b2ab', 'C', '1/5', '1/5', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('84f1dcec-94e2-57c8-b371-8a87e10754d6', 'b7968511-077a-5c42-9751-65be9867b2ab', 'D', '5', '5', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('d3e8ab8d-4362-5d41-a99e-1d51475593a3', 'b7968511-077a-5c42-9751-65be9867b2ab', '1. Simplify each radical:\n- √20 = √(4 × 5) = 2√5\n- √45 = √(9 × 5) = 3√5\n- √75 = √(25 × 3) = 5√3\n2. Numerator: 6(2√5) - 3(3√5) = 12√5 - 9√5 = 3√5.\n3. Denominator: 3(5√3) = 15√3.\n4. Fraction: (3√5) / (15√3) = (√5) / (5√3).\n5. Rationalize denominator: (√5 × √3) / (5√3 × √3) = √15 / 15.\nTherefore, the correct answer is B.', 'Numerator = 3√5, Denominator = 15√3. (3√5)/(15√3) = √5/(5√3) = √15/15.', 'Simplifying and rationalizing radical surds.', 'Forgetting to multiply 5 by 3 when multiplying √3 by √3 in denominator.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('299642fc-1ea5-5f72-a9aa-89b5dc629c56', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Let set A = {1, 3, 5, 6, 8, 10} and set B = {2, 5, 8, 11}. What is the symmetric difference A △ B?', 'ስብስብ A = {1, 3, 5, 6, 8, 10} እና B = {2, 5, 8, 11} ቢሆኑ፣ የሁለቱ ስብስቦች ሲሜትሪክ ልዩነት A △ B ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', 27) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('edca71b6-86ef-5be1-a5ff-e33d50f26cc0', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', 'A', '{1, 2, 3, 5, 6, 8, 10, 11}', '{1, 2, 3, 5, 6, 8, 10, 11}', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a12ac7e0-ac69-5f16-bff1-52cf28476767', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', 'B', '{2, 11}', '{2, 11}', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cbd20981-04e2-5b7d-a60d-7783937bdca2', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', 'C', '{1, 2, 3, 6, 10, 11}', '{1, 2, 3, 6, 10, 11}', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0d15b493-09fa-55ef-b904-d0311ef9dca8', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', 'D', '{1, 3, 6, 10}', '{1, 3, 6, 10}', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('a346d50a-9547-5c64-8b4a-ff8dbee3c2fe', '299642fc-1ea5-5f72-a9aa-89b5dc629c56', '1. Symmetric difference A △ B = (A ∪ B) \ (A ∩ B).\n2. Intersection A ∩ B = {5, 8}.\n3. Elements exclusively in A or B: {1, 2, 3, 6, 10, 11}.\nTherefore, the correct answer is C.', 'Remove shared numbers {5, 8} from the union: {1, 2, 3, 6, 10, 11}.', 'Symmetric difference of sets: A △ B = (A \ B) ∪ (B \ A).', 'Selecting the full union instead of removing the intersection.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('a289beda-6182-500a-b595-c2087714bc37', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the population variance (σ²) of the dataset {2, 3, 4, 5, 7}?', 'የዳታ ስብስብ {2, 3, 4, 5, 7} ፖፑሌሽን ቫሪያንስ (σ²) ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'a289beda-6182-500a-b595-c2087714bc37', 28) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('28b9a761-1ab2-5058-b20e-b3fea90d9730', 'a289beda-6182-500a-b595-c2087714bc37', 'A', '2.46', '2.46', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('41776c09-8e5a-5306-8986-f559ebb9b7c8', 'a289beda-6182-500a-b595-c2087714bc37', 'B', '2.96', '2.96', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0cae7919-3c8e-5485-9e2c-2875de00ae10', 'a289beda-6182-500a-b595-c2087714bc37', 'C', '3.06', '3.06', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a96e5786-a67b-5321-a581-ccbe2ad54c74', 'a289beda-6182-500a-b595-c2087714bc37', 'D', '3.70', '3.70', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('63063707-d7ba-5d63-9b9e-6d357defe3ef', 'a289beda-6182-500a-b595-c2087714bc37', '1. Mean μ = 21 / 5 = 4.2.\n2. Sum of squared deviations = 4.84 + 1.44 + 0.04 + 0.64 + 7.84 = 14.80.\n3. Population variance σ² = 14.80 / 5 = 2.96.\nTherefore, the correct answer is B.', 'Mean is 4.2. Sum of squared deviations is 14.80. Variance = 14.80 / 5 = 2.96.', 'Population variance formula: σ² = Σ(x - μ)² / N.', 'Dividing by N-1 (sample variance, 3.70) instead of N=5.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which pair of events represents dependent events?', 'ከሚከተሉት የክስተት ጥንዶች ውስጥ ጥገኛ የሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 29) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('80147b94-9b7c-5381-a03e-3402677e9247', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 'A', 'Tossing two fair coins and observing one head and one tail', 'ሁለት ሳንቲሞችን መወርወር', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c32778ea-42e3-5fab-b18c-e54acdbea815', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 'B', 'Drawing two cards successively from a standard deck without replacement', 'ከካርታ ሳጥን ውስጥ ሁለት ካርታዎችን ሳያስመልሱ በቅደም ተከተል መምዘዝ', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('15f9adcc-9496-5445-bd70-aea22362e03b', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 'C', 'Drawing two balls successively from an urn with replacement', 'ሁለት ኳሶችን መልሶ በማስቀመጥ መምዘዝ', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d871873c-69d7-5db4-9d54-ae06814cc356', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', 'D', 'Tossing a coin and rolling a die at the same time', 'ሳንቲም እና ዳይስ በአንድ ጊዜ መወርወር', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('414ab329-46f3-5ef8-a5a1-5169cb8d7dc4', '8ac8fce8-0b80-5636-9850-a6d5a1c0817f', '1. Drawing without replacement changes the total outcomes and probability for the next draw.\n2. Therefore, the second draw is dependent on the first.\nTherefore, the correct answer is B.', 'Without replacement means the first draw changes the deck, creating dependence.', 'Independent vs Dependent events in probability.', 'Confusing with replacement (independent) with without replacement (dependent).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'If lim_{x→2} f(x) = 6 and lim_{x→2} g(x) = -9, what is the value of lim_{x→2} [f(x) - g(x)] / [2f(x) - 7]?', 'lim_{x→2} f(x) = 6 እና lim_{x→2} g(x) = -9 ቢሆኑ፣ lim_{x→2} [f(x) - g(x)] / [2f(x) - 7] ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 30) ON CONFLICT (exam_id, question_id) DO NOTHING;
