INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1437fe3e-b23a-5eef-bd68-8e5d727208d6', '3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 'B', '-3', '-3', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b994c71e-42d4-5ad6-83a5-a4a372f894c8', '3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 'C', '15', '15', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('dd40d308-1271-5b6a-a5e3-10aca1495256', '3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 'D', '-15', '-15', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('3ef8883c-ebc3-586b-8a69-eaca06a2f0a0', '3621f9a9-9317-5ca0-ad25-7dfc1c0c7d1d', 'Numerator = 6 - (-9) = 15.\nDenominator = 2(6) - 7 = 5.\nLimit = 15 / 5 = 3.\nTherefore, the correct answer is A.', '(6 - (-9)) / (12 - 7) = 15 / 5 = 3.', 'Limit laws for rational combinations.', 'Sign error: 6 - (-9) = 15, not -3.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('2727fe13-ad90-5a62-a988-bb31b35e46a9', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Which statement is universally true for real-valued functions?', 'ስለ ፈንክሽኖች ከሚከተሉት አረፍተ ነገሮች ውስጥ ሁልጊዜ እውነት የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '2727fe13-ad90-5a62-a988-bb31b35e46a9', 31) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('81c83ad5-a77a-568a-8158-4892668bdefc', '2727fe13-ad90-5a62-a988-bb31b35e46a9', 'A', 'y = 0 is tangent to f(x) = |x| at (0, 0)', 'y = 0 ለ f(x) = |x| ታንጀንት መስመር ነው', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f8330c5e-309e-5234-ac48-0903c1fdb75e', '2727fe13-ad90-5a62-a988-bb31b35e46a9', 'B', 'If a function is differentiable at a, then it is continuous at a', 'አንድ ፈንክሽን በ a ላይ ዲፈረንሼብል ከሆነ በ a ላይ ቀጣይ ነው', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cbf0e3a9-1d51-55eb-99be-75bc2bc4e6f9', '2727fe13-ad90-5a62-a988-bb31b35e46a9', 'C', 'If f''(a) = 0, the tangent line is y = a', 'f''(a) = 0 ከሆነ የታንጀንት መስመሩ y = a ነው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cee5276b-2a3b-5883-be10-30eb6d8c9c15', '2727fe13-ad90-5a62-a988-bb31b35e46a9', 'D', 'If f and g are differentiable at a, then f/g is always differentiable at a', 'f እና g ዲፈረንሼብል ከሆኑ f/g ሁልጊዜ ዲፈረንሼብል ነው', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('6be899ec-bd95-5ea9-af6a-5425555a7948', '2727fe13-ad90-5a62-a988-bb31b35e46a9', '1. Differentiability strictly implies continuity at a point.\n2. The converse does not hold (e.g. |x| is continuous at 0 but not differentiable).\nTherefore, the correct answer is B.', 'Differentiable ⇒ Continuous.', 'Differentiability implies continuity.', 'Thinking continuity guarantees differentiability.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('7cef3229-6d1f-528b-b57c-138326f28e7c', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'For what value of constant ''a'' is the piecewise function f(x) = { ax + 3 for x ≥ 1; x² - 2x + 3 for x < 1 } continuous at x = 1?', 'የተከፋፈለ ፈንክሽን f(x) = { ax + 3 for x ≥ 1; x² - 2x + 3 for x < 1 } በ x = 1 ላይ ቀጣይ እንዲሆን የ a ዋጋ ስንት መሆን አለበት?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '7cef3229-6d1f-528b-b57c-138326f28e7c', 32) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b44adf0c-8836-522e-8a6a-d4fcbcb04bab', '7cef3229-6d1f-528b-b57c-138326f28e7c', 'A', '1', '1', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f0547830-dbd4-5743-b273-6e399a85673f', '7cef3229-6d1f-528b-b57c-138326f28e7c', 'B', '-1', '-1', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('334273d1-cfb1-54c3-9a89-a3deb294159b', '7cef3229-6d1f-528b-b57c-138326f28e7c', 'C', '3', '3', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1bb0b146-41bf-567a-b04b-7a2ab93ffe94', '7cef3229-6d1f-528b-b57c-138326f28e7c', 'D', '4', '4', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('b3f3360a-5c88-57ac-abc6-831e78342b08', '7cef3229-6d1f-528b-b57c-138326f28e7c', 'Left limit at x=1 is 1² - 2(1) + 3 = 2.\nRight value is a(1) + 3 = a + 3.\nSet equal: a + 3 = 2 ⇒ a = -1.\nTherefore, the correct answer is B.', 'Left limit = 2. Right limit = a + 3. So a = -1.', 'Piecewise function continuity condition.', 'Arithmetic sign error: 2 - 3 = -1.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('3e40f82a-40ce-5674-a702-da3e727a3932', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Find the derivative f''(0) at x = 0 for the function f(x) = (x eˣ) / cos(x).', 'የፈንክሽን f(x) = (x eˣ) / cos(x) ዲሪቬቲቭ በ x = 0 ላይ ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '3e40f82a-40ce-5674-a702-da3e727a3932', 33) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('5e11d658-f1f3-51db-a85f-b3f23e5af430', '3e40f82a-40ce-5674-a702-da3e727a3932', 'A', '2', '2', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0e45678c-3c05-565c-a674-d43d4d1dc8b2', '3e40f82a-40ce-5674-a702-da3e727a3932', 'B', '-1', '-1', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2a5cf0dc-75b4-59e3-9681-a5b431350ebe', '3e40f82a-40ce-5674-a702-da3e727a3932', 'C', '1', '1', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('114997bf-e3e6-50cb-a351-28c5006848ac', '3e40f82a-40ce-5674-a702-da3e727a3932', 'D', '0', '0', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('330a074e-a9e7-5d44-b7ce-87436d4f3df3', '3e40f82a-40ce-5674-a702-da3e727a3932', 'f(x) = x eˣ sec(x).\nf''(0) = (1)(e⁰)(sec 0) + (0)(...) = 1(1)(1) = 1.\nTherefore, the correct answer is C.', 'At x = 0, the only non-zero term is (d/dx x) · e⁰ · sec(0) = 1.', 'Product rule for calculus derivatives.', 'Assuming the whole expression evaluates to 0 because of x.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which statement is true regarding bounded sequences of real numbers?', 'ስለ ወሰን ያላቸው ቅደም ተከተሎች እውነት የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 34) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('aaa0a4c6-0df1-5743-afa8-7e9399cccd0f', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 'A', 'Every bounded sequence converges', 'ማንኛውም ወሰን ያለው ተከታታይ ይሰበሰባል', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('35770216-0996-5eb9-a427-d0b216c521ac', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 'B', 'Every increasing bounded sequence converges to its greatest lower bound', 'እየጨመረ የሚሄድ ተከታታይ ወደ ትንሹ ወሰን ይሰበሰባል', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('415c9910-bba0-5ec1-9c14-2fa00ccb946b', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 'C', 'Every decreasing bounded sequence converges to its least upper bound', 'እየቀነሰ የሚሄድ ተከታታይ ወደ ትልቁ ወሰን ይሰበሰባል', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('259406a6-cbfc-5130-b0f5-6b18f3604db6', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 'D', 'Every monotone bounded sequence converges', 'ማንኛውም ሞኖቶን እና ወሰን ያለው ተከታታይ ይሰበሰባል', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('95fa4105-8d40-522c-87dc-11189d0a0223', '69cd4dd6-a722-5f5e-8a67-e0217ea5b583', 'By the Monotone Convergence Theorem, every sequence that is both monotone and bounded converges.\nTherefore, the correct answer is D.', 'Monotone + Bounded = Convergent.', 'Monotone Convergence Theorem.', 'Thinking all bounded sequences converge (e.g. (-1)ⁿ oscillates).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('f8170da4-42af-5dd7-9b25-0f3a036922c4', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Suppose f is twice continuously differentiable, f''''(3) = 5, and g(x) = f(2x + 3). What is the value of g''''(0)?', 'f ሁለት ጊዜ ዲፈረንሼብል ሆኖ f''''(3) = 5 እና g(x) = f(2x + 3) ቢሆን፣ የ g''''(0) ዋጋ ስንት ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 35) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f3dfd908-b9f4-5878-ba69-c0f6fb266f2b', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 'A', '40', '40', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e92b46dd-e405-59cb-bfb9-e417a4e0021b', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 'B', '20', '20', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9c05e34c-fa89-5892-9539-001d31ec9cc6', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 'C', '5', '5', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bf1de1ca-1076-5de8-8569-c6370f82ab63', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 'D', '10', '10', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('b88da3fe-e778-58e2-8cf8-e63b2eb43a00', 'f8170da4-42af-5dd7-9b25-0f3a036922c4', 'g''(x) = 2 f''(2x + 3)\ng''''(x) = 4 f''''(2x + 3)\ng''''(0) = 4 f''''(3) = 4(5) = 20.\nTherefore, the correct answer is B.', 'Differentiating twice multiplies by 2 × 2 = 4. 4 × 5 = 20.', 'Chain rule for second derivatives.', 'Multiplying by 2 only once.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('ab8101c9-6106-5ac3-9951-d1289ea1c502', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'If f and g are continuous at x = a, which expression may fail to be continuous at a?', 'f እና g በ x = a ላይ ቀጣይ ቢሆኑ፣ በ a ላይ ቀጣይ ሳይሆን ሊቀር የሚችለው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 36) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0d9cec29-88e2-5abc-bafc-e7ef4bd07833', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 'A', '2f + 3g', '2f + 3g', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3c445bf9-4279-5977-9ee1-6763da9f65bf', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 'B', 'f · g', 'f · g', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ff76f25e-bc26-5080-99d7-63e32dd4c098', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 'C', 'f / g', 'f / g', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c77a900d-5ca7-5e55-bdc2-b31200bb37de', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 'D', 'f - 2g', 'f - 2g', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('ec612a81-7ef7-5ec9-87e5-ae18ca6e4dbf', 'ab8101c9-6106-5ac3-9951-d1289ea1c502', 'The quotient f / g is undefined and not continuous whenever the denominator g(a) = 0.\nTherefore, the correct answer is C.', 'f/g fails if the denominator g(a) = 0.', 'Continuity of rational combinations.', 'Ignoring the zero-denominator condition.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('27925b4f-3c8f-51c9-b913-130d3695050b', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Let f be a continuous function on ℝ and let c be in its domain. Which statement MUST be true?', 'f በ ℝ ላይ ቀጣይ ፈንክሽን ቢሆን እና c በዶሜኑ ውስጥ ቢገኝ፣ የግድ እውነት የሆነው የቱ ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '27925b4f-3c8f-51c9-b913-130d3695050b', 37) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9884afe1-e066-5685-a8c1-46ead2a04b39', '27925b4f-3c8f-51c9-b913-130d3695050b', 'A', 'An absolute maximum attained at an interior critical number is also a local maximum', 'በክሪቲካል ነጥብ ላይ የሚገኝ አብሶሉት ማክሲመም ሎካል ማክሲመምም ጭምር ነው', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bffbd5df-33fb-51e6-a575-c898aa419df8', '27925b4f-3c8f-51c9-b913-130d3695050b', 'B', 'If f''(c) = 0, then (c, f(c)) is an inflection point', 'f''(c) = 0 ከሆነ (c, f(c)) የኢንፍሌክሽን ነጥብ ነው', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('06361702-3ae9-5f1e-bcfa-b6b791aebc8a', '27925b4f-3c8f-51c9-b913-130d3695050b', 'C', 'If f(c) is a local minimum, then f''(c) = 0', 'f(c) ሎካል ሚኒመም ከሆነ f''(c) = 0 ነው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bd5cfc02-53b7-5920-94c2-92166308b20f', '27925b4f-3c8f-51c9-b913-130d3695050b', 'D', 'Every critical number produces a local extremum', 'ማንኛውም ክሪቲካል ነጥብ ሎካል ኤክስትሪመም ይሰጣል', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('943bef36-0bcf-5c45-a449-2ac41c3dcf47', '27925b4f-3c8f-51c9-b913-130d3695050b', 'An absolute maximum is ≥ all points in the entire domain, so it is also ≥ all points in a local neighborhood (local maximum).\nTherefore, the correct answer is A.', 'The global highest point is also the local highest point in its neighborhood.', 'Local vs global extrema definitions.', 'Assuming local extrema must have f''(c)=0 (ignores non-differentiable points).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('9813fc4b-a84b-5574-853e-338592020d4c', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the seventh term (a₇) of an arithmetic progression whose third term is a₃ = -4 and whose common difference is d = 5?', 'ሦስተኛ ተርሙ a₃ = -4 እና የጋራ ልዩነቱ d = 5 የሆነ አርቲሜቲክ ተከታታይ ሰባተኛ ተርም (a₇) ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '9813fc4b-a84b-5574-853e-338592020d4c', 38) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('44079663-b899-5562-8b9c-85c47e9b0bea', '9813fc4b-a84b-5574-853e-338592020d4c', 'A', '15', '15', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('542505f9-aa0d-56da-a2c9-ff33aa684a5d', '9813fc4b-a84b-5574-853e-338592020d4c', 'B', '-15', '-15', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c8868093-9be8-58c7-b8b4-b77d77932bcf', '9813fc4b-a84b-5574-853e-338592020d4c', 'C', '16', '16', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('496776d3-b1d8-59b5-a61b-bc10a900ff21', '9813fc4b-a84b-5574-853e-338592020d4c', 'D', '-16', '-16', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('8be23f05-e44f-5f2e-ad98-553eedd5fed4', '9813fc4b-a84b-5574-853e-338592020d4c', 'a₇ = a₃ + (7 - 3)d = -4 + 4(5) = -4 + 20 = 16.\nTherefore, the correct answer is C.', 'a₇ = -4 + 4(5) = 16.', 'Arithmetic progression term relations.', 'Multiplying by 7 instead of the step difference 4.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('cf46a9ef-10d0-55c6-9312-191ef113b33a', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'A rectangle has a fixed perimeter of 120 m. Which dimensions will maximize its enclosed area?', 'አጠቃላይ ዙሪያው 120 ሜትር የሆነ ሬክታንግል ከፍተኛ ስፋት እንዲኖረው የጎኖቹ ልክ ስንት መሆን አለበት?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 39) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c628a195-ce60-5c35-8019-a25ae5db1d78', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 'A', '50 m by 10 m', '50 ሜ በ 10 ሜ', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7d78420a-2a6c-51c7-9cc6-0628d565071a', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 'B', '30 m by 30 m', '30 ሜ በ 30 ሜ', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('dcbe2e48-bdfc-5554-9120-873d9c845689', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 'C', '35 m by 25 m', '35 ሜ በ 25 ሜ', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4f07a7a5-035f-521c-a17d-6cef33e75a00', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 'D', '40 m by 20 m', '40 ሜ በ 20 ሜ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('646dd818-bb32-5c46-832a-a8bc2307225c', 'cf46a9ef-10d0-55c6-9312-191ef113b33a', 'Perimeter = 2(l + w) = 120 ⇒ l + w = 60. Area = l(60 - l). Max at vertex l = 30, w = 30.\nTherefore, the correct answer is B.', 'For a fixed perimeter, a square has the largest area: 120 / 4 = 30 by 30.', 'Quadratic optimization of geometric area.', 'Choosing non-square pairs that sum to 60.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('6a8d74a2-389e-5506-8ec0-be34b9cbf461', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_2', 2014, 'Find the sum of the first 8 terms (S₈) of a geometric progression with first term a = 0.3 and common ratio r = 1/10.', 'የመጀመሪያ ተርሙ a = 0.3 እና የጋራ ሬሾው r = 1/10 የሆነ የጂኦሜትሪክ ተከታታይ የመጀመሪያ 8 ተርሞች ድምር (S₈) ስንት ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 40) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8f2488fe-a476-5a0b-8971-2132a5bc094d', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 'A', '(3/10) · (10⁸ - 1)/10⁸', '(3/10) · (10⁸ - 1)/10⁸', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f4c9c71c-9f92-50d9-83a5-3cbcbdeac12b', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 'B', '(1/3) · (10⁸ - 1)/10⁸', '(1/3) · (10⁸ - 1)/10⁸', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ab1861dc-8a39-5960-a230-f37b4e8b277a', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 'C', '(1/3) · (10⁸ - 1)/10⁷', '(1/3) · (10⁸ - 1)/10⁷', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3a0018b8-d209-5968-bd09-ae2be66a423e', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 'D', '(3/10) · (10⁸ - 1)/10⁹', '(3/10) · (10⁸ - 1)/10⁹', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('7ec891bc-7e07-50e8-9a52-309784ce3c5d', '6a8d74a2-389e-5506-8ec0-be34b9cbf461', 'S₈ = (3/10)(1 - 10⁻⁸) / (1 - 1/10) = (3/10)/(9/10) · (10⁸ - 1)/10⁸ = (1/3) · (10⁸ - 1)/10⁸.\nTherefore, the correct answer is B.', 'a / (1-r) = (3/10)/(9/10) = 1/3. Multiplied by (1 - 10⁻⁸) gives (1/3)(10⁸ - 1)/10⁸.', 'Geometric series sum formula: Sₙ = a(1 - rⁿ)/(1 - r).', 'Failing to simplify (3/10)/(9/10) to 1/3.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Suppose f is continuous on [a, b], differentiable on (a, b), and f(a) = f(b). Which theorem applies and what conclusion MUST hold?', 'f በ [a, b] ላይ ቀጣይ፣ በ (a, b) ላይ ዲፈረንሼብል ሆኖ f(a) = f(b) ቢሆን፣ የግድ እውነት የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 41) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('42d63c23-9129-5c8d-9f11-3fe6c227007d', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 'A', 'The function has a zero in (a, b)', 'ፈንክሽኑ በ (a, b) ውስጥ ዜሮ አለው', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4772415e-94bb-570e-a5bb-3906272e8134', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 'B', 'The function has a minimum in (a, b)', 'ፈንክሽኑ በ (a, b) ውስጥ ሚኒመም አለው', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e02ae7c7-943c-5dcf-bfbd-66d86b8b7c63', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 'C', 'The function has a maximum in (a, b)', 'ፈንክሽኑ በ (a, b) ውስጥ ማክሲመም አለው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('110cb9c5-b83c-53ec-a414-6797f36fe058', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 'D', 'There is some c ∈ (a, b) where the graph has a horizontal tangent (f''(c) = 0)', 'በ (a, b) ውስጥ አግድም ታንጀንት (f''(c) = 0) ያለው ነጥብ c አለ', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('ceca43ca-5ac8-5db1-adfe-95f0633b54ba', 'cb037be6-9b03-5b8b-b7ed-49fd65ef1666', 'By Rolle''s Theorem, there exists c ∈ (a, b) such that f''(c) = 0 (horizontal tangent).\nTherefore, the correct answer is D.', 'Rolle''s Theorem guarantees a horizontal tangent (f''(c) = 0).', 'Rolle''s Theorem in differential calculus.', 'Assuming the function must cross y=0.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('52b63fa3-4ffb-540a-80e6-895104a6ad27', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What is the perpendicular distance from point P(3, 4) to the line 3x + 4y - 5 = 0?', 'ከነጥብ P(3, 4) እስከ ቀጥተኛ መስመር 3x + 4y - 5 = 0 ያለው ቀጥተኛ ርቀት ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 42) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('55f13395-9bbd-5c4c-bd66-ed943d3d175c', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 'A', '5 units', '5 ዩኒት', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('536ca692-9f50-5d85-a430-c4311d697371', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 'B', '6 units', '6 ዩኒት', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('551f3f06-c1d7-5f9e-998f-bb8eaca1992f', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 'C', '4 units', '4 ዩኒት', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('10609996-41c8-5dac-b79c-58bc9d831c84', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 'D', '7 units', '7 ዩኒት', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('0fe2c548-c8bd-5b51-b327-bb9b15e9fe92', '52b63fa3-4ffb-540a-80e6-895104a6ad27', 'd = |3(3) + 4(4) - 5| / √(3² + 4²) = |9 + 16 - 5| / 5 = 20 / 5 = 4 units.\nTherefore, the correct answer is C.', '|20| / 5 = 4 units.', 'Point to line distance formula.', 'Forgetting the denominator √(3²+4²) = 5.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('ad37a11a-ea08-5d4c-b1ef-7a3a74acf982', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'A chord of an ellipse that passes through the center and is perpendicular to the major axis is called the:', 'በኤሊፕስ መሃል ነጥብ የሚያልፍ እና ለዋናው ዘንግ ቋሚ የሆነ ኮርድ ምን ይባላል?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
