INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ddb0fdf5-b898-5d6d-a0c7-e23215761f7e', 'ad37a11a-ea08-5d4c-b1ef-7a3a74acf982', 'D', 'Latus rectum', 'ላተስ ሬክተም', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('c4c994f4-d477-5cb0-a9aa-d249033065e1', 'ad37a11a-ea08-5d4c-b1ef-7a3a74acf982', 'The central chord perpendicular to the major axis is the minor axis.\nTherefore, the correct answer is B.', 'Perpendicular central chord of an ellipse = Minor axis.', 'Geometry of ellipse axes.', 'Confusing minor axis with latus rectum.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('406c7369-ce38-5ced-ae6c-bfd5ccf59101', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'If A is a 3 × 3 square matrix and det(A) = 5, what is the value of det(2A)?', 'A ባለ 3 × 3 ማትሪክስ ሆኖ det(A) = 5 ቢሆን፣ የ det(2A) ዋጋ ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
