INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('9c3132ad-ad9f-5412-ade8-930ac9cfecec', '406c7369-ce38-5ced-ae6c-bfd5ccf59101', 'det(2A) = 2³ det(A) = 8(5) = 40.\nTherefore, the correct answer is C.', 'det(2A) = 2³ × 5 = 8 × 5 = 40.', 'Determinant scalar rule: det(kA) = kⁿ det(A).', 'Multiplying by 2 instead of 2³ = 8.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('dee5371c-9db7-5898-a262-a937da80a774', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which augmented matrix represents the linear system { 2x + y + 3z = 4, x - z = 1, -4x + y = 3 }?', 'የቀረበውን ሊኒየር ሲስተም { 2x + y + 3z = 4, x - z = 1, -4x + y = 3 } የሚወክለው አውግሜንትድ ማትሪክስ የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
