INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('5664e1b1-a140-58df-a605-6bb0db564f20', 'dee5371c-9db7-5898-a262-a937da80a774', 'Row 1: [2, 1, 3 | 4], Row 2: [1, 0, -1 | 1], Row 3: [-4, 1, 0 | 3].\nMatches choice D.\nTherefore, the correct answer is D.', 'Coefficients: row 1 (2,1,3|4), row 2 (1,0,-1|1), row 3 (-4,1,0|3).', 'Augmented matrix form.', 'Missing zeros for absent variables.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('1b88cb91-6915-55b6-af94-24dc23bb9450', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which statement is NOT true regarding arguments and deductive validity in mathematical logic?', 'በማቲማቲካል ሎጂክ ውስጥ ስለ አርጉመንቶች እና ትክክለኛነት (validity) እውነት ያልሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '1b88cb91-6915-55b6-af94-24dc23bb9450', 46) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3e496720-0eee-55cc-b66e-9944b8d8ff3e', '1b88cb91-6915-55b6-af94-24dc23bb9450', 'A', 'An invalid argument is sometimes informally described as fallacious', 'ትክክል ያልሆነ አርጉመንት ስህተት (fallacious) ይባላል', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1519ae34-0bdd-5575-a85d-8f81a84bda80', '1b88cb91-6915-55b6-af94-24dc23bb9450', 'B', 'Validity can be formally checked using a truth table', 'ትክክለኛነትን በ Truth Table ማረጋገጥ ይቻላል', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8b0ca487-4b8c-5ee5-8981-f05c05620d50', '1b88cb91-6915-55b6-af94-24dc23bb9450', 'C', 'In a valid argument, the conclusion may be false when all premises are true', 'በቫሊድ አርጉመንት ውስጥ ሁሉም መነሻዎች እውነት ሆነው መደምደሚያው ውሸት ሊሆን ይችላል', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ced31c75-d2dc-5732-bab0-565785140442', '1b88cb91-6915-55b6-af94-24dc23bb9450', 'D', 'In a valid argument, true premises guarantee a true conclusion', 'በቫሊድ አርጉመንት ውስጥ እውነተኛ መነሻዎች እውነተኛ መደምደሚያን ያረጋግጣሉ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('0b7522ae-f2b9-59c4-8884-c58156fea01e', '1b88cb91-6915-55b6-af94-24dc23bb9450', '1. By definition, a deductive argument is valid if and only if it is impossible for all premises to be true while the conclusion is false simultaneously.\n2. Statement C asserts that the conclusion may be false with true premises, which directly contradicts the definition of validity.\nTherefore, the statement that is NOT true is C.', 'A valid argument cannot have true premises and a false conclusion.', 'Definition of logical validity in deductive logic.', 'Confusing validity of an argument structure with soundness or empirical truth.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b7390af9-6f88-50bd-9311-0362107ecd31', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which conditional statement has a converse whose truth value is FALSE?', 'ከሚከተሉት ሁኔታዊ አረፍተ ነገሮች (conditional statements) ውስጥ ግልባጩ (converse) ውሸት (False) የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b7390af9-6f88-50bd-9311-0362107ecd31', 47) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f745e362-ff70-5d8c-858f-8697a417b712', 'b7390af9-6f88-50bd-9311-0362107ecd31', 'A', 'If 6 is prime, then 4 is even', '6 ፕራይም ቁጥር ከሆነ፣ 4 ኢቭን (ተጋማሽ) ቁጥር ነው', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8229033f-3993-5a4e-a6d3-e61b852058f9', 'b7390af9-6f88-50bd-9311-0362107ecd31', 'B', 'If humans are immortal, then Earth does not rotate around the Sun', 'ሰዎች ሟቾች ካልሆኑ፣ ምድር በፀሐይ ዙሪያ አትዞርም', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ea9d72ab-5295-586d-afd2-a10879ef1410', 'b7390af9-6f88-50bd-9311-0362107ecd31', 'C', 'If Derartu Tulu was born on October 21, 1971, then 6 is prime', 'ደራርቱ ቱሉ በጥቅምት 21 1971 ከተወለደች፣ 6 ፕራይም ቁጥር ነው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a80c798b-2588-5f5a-b1b1-f12e00be107b', 'b7390af9-6f88-50bd-9311-0362107ecd31', 'D', 'If humans are mortal, then Earth does not rotate around the Sun', 'ሰዎች ሟች ከሆኑ፣ ምድር በፀሐይ ዙሪያ አትዞርም', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('eef9dd4a-1fdc-539c-9437-ce65e84c5e7a', 'b7390af9-6f88-50bd-9311-0362107ecd31', '1. For the conditional ''If P, then Q'' (P ⇒ Q), its converse is ''If Q, then P'' (Q ⇒ P).\n2. For choice A: P = ''6 is prime'' (False), Q = ''4 is even'' (True).\n3. The converse is: ''If 4 is even, then 6 is prime'' (True ⇒ False), which is FALSE.\n4. In all other choices, the converse has a false hypothesis or true conclusion, resulting in a truth value of True.\nTherefore, the correct answer is A.', 'Converse of A is ''If 4 is even (True), then 6 is prime (False)'', which evaluates to False.', 'Truth tables of conditional (P ⇒ Q) and converse (Q ⇒ P) propositions.', 'Evaluating the original statement instead of its converse.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('009071f9-4abf-500f-8c0a-473f77db64f3', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Solve the logarithmic equation: log(x² - 3) = 2 log(x - 1)', 'የሎጋሪዝም እኩልዮሹን መፍትሔ ፈልጉ: log(x² - 3) = 2 log(x - 1)', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '009071f9-4abf-500f-8c0a-473f77db64f3', 48) ON CONFLICT (exam_id, question_id) DO NOTHING;
