INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a363f8ca-71ce-5343-a511-4d13b3e43dbc', '009071f9-4abf-500f-8c0a-473f77db64f3', 'C', '{4}', '{4}', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b6d13052-dadf-5084-a64a-b4907b32708d', '009071f9-4abf-500f-8c0a-473f77db64f3', 'D', '∅ (Empty set)', '∅ (ባዶ ስብስብ)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('daf2dfd1-4264-55ab-89fc-c0fcdac318c3', '009071f9-4abf-500f-8c0a-473f77db64f3', '1. Domain restrictions: x - 1 > 0 ⇒ x > 1, and x² - 3 > 0 ⇒ x > √3 ≈ 1.732.\n2. Use power rule: 2 log(x - 1) = log((x - 1)²).\n3. Equate arguments: x² - 3 = (x - 1)² = x² - 2x + 1.\n4. Cancel x²: -3 = -2x + 1 ⇒ 2x = 4 ⇒ x = 2.\n5. Check domain: x = 2 > √3, valid.\nTherefore, the solution set is {2} (Choice B).', 'x² - 3 = (x - 1)² ⇒ x² - 3 = x² - 2x + 1 ⇒ 2x = 4 ⇒ x = 2.', 'Properties of logarithms and domain validation for extraneous solutions.', 'Failing to verify the domain restriction x > 1.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('bc6c8947-6819-5815-895c-36f0e6c57e96', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'Which trigonometric identity/equality is true for all angles?', 'ከሚከተሉት የትሪጎኖሜትሪ እኩልነቶች ውስጥ ትክክል የሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'bc6c8947-6819-5815-895c-36f0e6c57e96', 49) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3ce50936-3a53-5b24-a44a-b542b5204abb', 'bc6c8947-6819-5815-895c-36f0e6c57e96', 'A', 'tan(75°) = tan(105°)', 'tan(75°) = tan(105°)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('728e419c-9c64-5530-a0e2-133ccb4a49cd', 'bc6c8947-6819-5815-895c-36f0e6c57e96', 'B', 'sin(75°) = cos(105°)', 'sin(75°) = cos(105°)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a56050ff-a97b-5b1c-ba36-bfef00156882', 'bc6c8947-6819-5815-895c-36f0e6c57e96', 'C', 'cos(120°) = cos(60°)', 'cos(120°) = cos(60°)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f0dd08df-6f69-5875-8ff9-a0318a8b9d21', 'bc6c8947-6819-5815-895c-36f0e6c57e96', 'D', 'sin(120°) = sin(60°)', 'sin(120°) = sin(60°)', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('0aace992-7140-59b7-aced-70901713e3cb', 'bc6c8947-6819-5815-895c-36f0e6c57e96', '1. Using the supplementary angle identity: sin(180° - θ) = sin(θ).\n2. For θ = 60°: sin(180° - 60°) = sin(120°) = sin(60°) = √3/2.\n3. cos(120°) = -cos(60°), tan(105°) = -tan(75°).\nTherefore, the correct identity is D.', 'sin(120°) = sin(180° - 60°) = sin(60°) = √3/2.', 'Quadrant II trigonometric reduction formulas.', 'Thinking cosine is positive in the second quadrant.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Solve the quadratic inequality: x² - 5x + 6 ≤ 0', 'የኳድራቲክ ኢኳሊቲውን መፍትሔ ፈልጉ: x² - 5x + 6 ≤ 0', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 50) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c2ae86c3-6e95-561f-8d09-94fadd1cb7da', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 'A', '[0, 2]', '[0, 2]', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a9509c71-f27e-5904-b940-bd4789f66814', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 'B', '[2, 3]', '[2, 3]', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('6af0966f-9c57-5803-80f9-d183450b925f', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 'C', '(3, ∞)', '(3, ∞)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2831de18-bdf3-5c86-86b3-22099d456f29', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', 'D', '(-∞, 2]', '(-∞, 2]', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('fd2c8ae8-cd3b-5ac8-90e8-8df1374c4bf4', '0c4d00ae-ac33-5fd1-85c2-0cd03076be29', '1. Factor the quadratic polynomial: x² - 5x + 6 = (x - 2)(x - 3).\n2. The roots are x = 2 and x = 3.\n3. The parabola y = (x - 2)(x - 3) opens upward, so it is ≤ 0 between and including its real roots.\n4. Solution interval: 2 ≤ x ≤ 3, or [2, 3].\nTherefore, the correct answer is B.', '(x - 2)(x - 3) ≤ 0 has roots 2 and 3, so solution is [2, 3].', 'Solving quadratic inequalities using sign charts / parabolas.', 'Using open interval (2, 3) instead of closed interval [2, 3] for ≤.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'What point divides the directed line segment from P(0, 1) to Q(5, 6) in the ratio 2 : 3 measured from P?', 'ከነጥብ P(0, 1) እስከ Q(5, 6) ያለውን የመስመር ክፍል በ 2:3 ንፅፅር ከ P አንጻር የሚከፍለው ነጥብ የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 51) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('9d584c20-9532-5fe0-b30b-4d582bab82df', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 'A', '(2, 3)', '(2, 3)', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('5f6d8173-771a-587b-8b7f-f5d3fb8a8b8d', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 'B', '(0, 2)', '(0, 2)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('71e2cd5a-5b23-5ffb-805a-7032bafdc196', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 'C', '(3, 2)', '(3, 2)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('23f806fb-4919-55de-9730-904f35a6af87', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', 'D', '(0, 3)', '(0, 3)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('d7cc957d-a300-5b8e-bf93-bbc7d22b09f4', '2f9f930c-3a93-5d1f-90a0-5ba8a3bb17e6', '1. Section formula for ratio m : n (here m=2, n=3):\n- x = (m x₂ + n x₁) / (m + n) = (2(5) + 3(0)) / (2 + 3) = 10 / 5 = 2\n- y = (m y₂ + n y₁) / (m + n) = (2(6) + 3(1)) / (2 + 3) = (12 + 3) / 5 = 15 / 5 = 3\n2. The dividing point is (2, 3).\nTherefore, the correct answer is A.', 'x = (2×5 + 3×0)/5 = 2. y = (2×6 + 3×1)/5 = 3. Point is (2, 3).', 'Internal section formula for dividing a line segment in a given ratio.', 'Dividing by 3 or 2 instead of the sum m + n = 5.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('ae36c708-db80-5541-b74c-1933f33056e9', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'Which exact trigonometric evaluation is correct?', 'ከሚከተሉት የትሪጎኖሜትሪ ዋጋዎች ውስጥ ትክክል የሆነው የቱ ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'ae36c708-db80-5541-b74c-1933f33056e9', 52) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('fd8a42ce-cd7f-55b6-b397-d31de029b195', 'ae36c708-db80-5541-b74c-1933f33056e9', 'A', 'sin(-120°) = 0.5', 'sin(-120°) = 0.5', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ddbfba24-75be-5242-8ecd-8e4a1e81175a', 'ae36c708-db80-5541-b74c-1933f33056e9', 'B', 'cos(-120°) = -0.5', 'cos(-120°) = -0.5', true, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d6955a98-62d9-52ec-86a9-35491029b319', 'ae36c708-db80-5541-b74c-1933f33056e9', 'C', 'tan(-120°) = -1', 'tan(-120°) = -1', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('bd93c67e-d4d4-5cb0-a45a-2429a6bbf4c1', 'ae36c708-db80-5541-b74c-1933f33056e9', 'D', 'cos(-60°) = √3/2', 'cos(-60°) = √3/2', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('dcc8c0b9-87f6-50b8-813f-37e60a7de139', 'ae36c708-db80-5541-b74c-1933f33056e9', '1. Cosine is an even function: cos(-θ) = cos(θ).\n2. cos(-120°) = cos(120°).\n3. In Quadrant II: cos(120°) = cos(180° - 60°) = -cos(60°) = -1/2 = -0.5.\nTherefore, the correct answer is B.', 'cos(-120°) = cos(120°) = -cos(60°) = -0.5.', 'Even/Odd parity and reference angles of trigonometric functions.', 'Treating cosine as an odd function (negating the angle).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Which function maps the set of all real numbers ℝ onto the interval [0, ∞)?', 'የሁሉንም ሪል ቁጥሮች ℝ ወደ ኢንተርቫል [0, ∞) የሚያገናኘው (onto) ፈንክሽን የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 53) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a95b306c-e0b7-50e0-92b4-86b999169fcf', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 'A', 'f(x) = √(x²)', 'f(x) = √(x²)', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a9efc2d9-841d-531a-89a4-6c8cbd394f06', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 'B', 'f(x) = |x| + 2', 'f(x) = |x| + 2', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8d5eb7b7-cc9d-5e4b-a65c-0eb070a3e1c2', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 'C', 'f(x) = x² + 1', 'f(x) = x² + 1', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4b79943c-1b85-548c-97b6-f83c03a97af2', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', 'D', 'f(x) = 2ˣ', 'f(x) = 2ˣ', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('ff5b069d-b406-50fa-9c75-00bdfbbc1158', 'a7efa161-5504-5ebe-8c25-dc5f4fa4495e', '1. By principal square root definition, √(x²) = |x|.\n2. For all x ∈ ℝ, |x| ≥ 0, and for any y ∈ [0, ∞), choosing x = y gives f(y) = y, so the range is exactly [0, ∞).\n3. Ranges of the others: |x| + 2 gives [2, ∞); x² + 1 gives [1, ∞); 2ˣ gives (0, ∞) (never equals 0).\nTherefore, the correct answer is A.', '√(x²) = |x|, whose range is exactly [0, ∞) including 0.', 'Range determination of absolute value, radical, and exponential functions.', 'Thinking 2ˣ includes 0 (exponential function range is strictly positive (0, ∞)).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Simplify the rational expression for x ≠ 2: (4x⁴ - 64) / (2 - x)', 'የአልጀብራ ክፍልፋዩን አቃልሉ (x ≠ 2): (4x⁴ - 64) / (2 - x)', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 54) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d98ff06a-519e-5171-9801-8f03d082149b', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 'A', '4(x + 2)(x² + 4)', '4(x + 2)(x² + 4)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('529eec58-5a07-5b1c-84e7-213ec3fedde6', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 'B', '4(x - 2)(x² - 4)', '4(x - 2)(x² - 4)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('a09a0453-3396-53a8-893f-16b59ac36dea', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 'C', '-4(x + 2)(x² + 4)', '-4(x + 2)(x² + 4)', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('3ac8e1f3-2db9-5cb3-8b98-705380ccdcb1', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', 'D', '-4(x - 2)(x² + 4)', '-4(x - 2)(x² + 4)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('a0bda402-1236-5079-8415-23aa6abc242f', 'c0d2ea31-17fe-5e3b-ac48-19554a3542c2', '1. Factor numerator using difference of squares:\n4x⁴ - 64 = 4(x⁴ - 16) = 4(x² - 4)(x² + 4) = 4(x - 2)(x + 2)(x² + 4).\n2. Denominator is (2 - x) = -(x - 2).\n3. Cancel the common factor (x - 2):\n[4(x - 2)(x + 2)(x² + 4)] / [-(x - 2)] = -4(x + 2)(x² + 4).\nTherefore, the correct answer is C.', '4(x-2)(x+2)(x²+4) / -(x-2) = -4(x+2)(x²+4).', 'Factoring polynomials using difference of squares and sign reversal.', 'Forgetting that (2 - x) = -(x - 2), missing the negative sign.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('38d59825-33c0-5965-8c34-9dc0e544d2a7', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Birr 20,000 is deposited at a 12% nominal annual interest rate compounded monthly. How many years will it take for the investment to double?', '20,000 ብር በየወሩ በሚታሰብ 12% ዓመታዊ ወለድ ቢቀመጥ፣ ገንዘቡ እጥፍ (40,000) ለመሆን ስንት ዓመታት ይፈጃል?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '38d59825-33c0-5965-8c34-9dc0e544d2a7', 55) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('908f42e6-000d-578d-b381-52c3770c9ea0', '38d59825-33c0-5965-8c34-9dc0e544d2a7', 'A', '7.59 years', '7.59 ዓመታት', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b7996539-422a-54b9-ba5a-b149e49bb728', '38d59825-33c0-5965-8c34-9dc0e544d2a7', 'B', '6.00 years', '6.00 ዓመታት', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7f72586f-98fa-52cb-a1d2-2400e35370e5', '38d59825-33c0-5965-8c34-9dc0e544d2a7', 'C', '5.81 years', '5.81 ዓመታት', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('aacec783-8dfd-55f8-a476-7a74b06b97cb', '38d59825-33c0-5965-8c34-9dc0e544d2a7', 'D', '5.00 years', '5.00 ዓመታት', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('78391368-9b8a-53c0-a79e-49977dcde5a8', '38d59825-33c0-5965-8c34-9dc0e544d2a7', '1. Compound interest formula: A = P(1 + r/n)^(nt).\n2. To double: A/P = 2, with r = 0.12, n = 12 months/year.\n3. Monthly multiplier: 1 + 0.12/12 = 1 + 0.01 = 1.01.\n4. Equation: 2 = (1.01)^(12t).\n5. Take natural logs: ln(2) = 12t · ln(1.01) ⇒ t = ln(2) / [12 ln(1.01)].\n6. Computation: ln(2) ≈ 0.693147, 12 × ln(1.01) ≈ 12 × 0.0099503 = 0.119404.\n7. t = 0.693147 / 0.119404 ≈ 5.805 ≈ 5.81 years.\nTherefore, the correct answer is C.', 't = ln(2) / (12 × ln(1.01)) ≈ 0.6931 / 0.1194 ≈ 5.81 years.', 'Compound interest doubling time formula.', 'Using simple interest (100/12 = 8.33) or annual compounding (ln2/ln1.12 = 6.12).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('1146c50c-b30e-54e0-813c-65ed3a1f1969', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'For the 3 × 3 matrix A = [1 3 5; 6 4 2; 9 7 0], which statement regarding minors and cofactors is TRUE?', 'ለ 3 × 3 ማትሪክስ A = [1 3 5; 6 4 2; 9 7 0] ስለ ማይነሮች እና ኮፋክተሮች እውነት የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '1146c50c-b30e-54e0-813c-65ed3a1f1969', 56) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('4bf576c0-3d6d-5e00-84b5-241e4f1eb2ba', '1146c50c-b30e-54e0-813c-65ed3a1f1969', 'A', 'The minor of entry 3 is 18', 'የቁጥር 3 ማይነር 18 ነው', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0b298124-6ad2-573a-9a6c-d451af595dfa', '1146c50c-b30e-54e0-813c-65ed3a1f1969', 'B', 'The cofactor of entry 5 is -6', 'የቁጥር 5 ኮፋክተር -6 ነው', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('457ee3af-50dc-50ca-90ec-4c97a29fe45e', '1146c50c-b30e-54e0-813c-65ed3a1f1969', 'C', 'The minor of entry 0 is 14', 'የቁጥር 0 ማይነር 14 ነው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2529e0d6-66c2-5fdf-b57f-9cd45b04055f', '1146c50c-b30e-54e0-813c-65ed3a1f1969', 'D', 'The cofactor of the entry 1 is -14', 'የቁጥር 1 ኮፋክተር -14 ነው', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('be0610dd-f385-5b63-a9d8-7d1d88d2e0f5', '1146c50c-b30e-54e0-813c-65ed3a1f1969', '1. Entry a₁₁ = 1 is in Row 1, Column 1.\n2. Minor M₁₁ = det([4 2; 7 0]) = 4(0) - 2(7) = 0 - 14 = -14.\n3. Cofactor C₁₁ = (-1)^(1+1) M₁₁ = (+1)(-14) = -14.\n4. Let''s check others: Minor of 3 (M₁₂) = det([6 2; 9 0]) = 0 - 18 = -18 (not 18); Cofactor of 5 (C₁₃) = +det([6 4; 9 7]) = 42 - 36 = +6 (not -6).\nTherefore, statement D is TRUE.', 'For entry 1: C₁₁ = +1 × det([4 2; 7 0]) = 0 - 14 = -14.', 'Definitions of Matrix Minors and Signed Cofactors: C_ij = (-1)^(i+j) M_ij.', 'Sign errors in cofactor formula (-1)^(i+j).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('b6fffad1-b704-55a6-a316-21638788ee2b', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Consider points A(-2, 1), B(3, 0), C(3, -1), and D(1, 1). If u = AB and v = CD, what is the vector u - v?', 'ነጥቦች A(-2, 1)፣ B(3, 0)፣ C(3, -1) እና D(1, 1) ተሰጥተው u = AB እና v = CD ቢሆኑ፣ ቬክተር u - v ስንት ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'b6fffad1-b704-55a6-a316-21638788ee2b', 57) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('17a7e348-2ad2-5420-910b-2c935453d640', 'b6fffad1-b704-55a6-a316-21638788ee2b', 'A', '(3, 1)', '(3, 1)', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('6e72439f-7f78-5fbf-a1f0-4dc8b2552699', 'b6fffad1-b704-55a6-a316-21638788ee2b', 'B', '(-7, 1)', '(-7, 1)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7bef64b2-4547-5b38-b1d3-6f45821a40d9', 'b6fffad1-b704-55a6-a316-21638788ee2b', 'C', '(1, 3)', '(1, 3)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2f88b449-42c0-5d2e-895f-0d15f511961d', 'b6fffad1-b704-55a6-a316-21638788ee2b', 'D', '(7, -3)', '(7, -3)', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('45a4f6f5-4aa0-5bb5-a60e-96414daf3ec3', 'b6fffad1-b704-55a6-a316-21638788ee2b', '1. Vector u = B - A = (3 - (-2), 0 - 1) = (5, -1).\n2. Vector v = D - C = (1 - 3, 1 - (-1)) = (-2, 2).\n3. Vector difference u - v = (5 - (-2), -1 - 2) = (5 + 2, -3) = (7, -3).\nTherefore, the correct answer is D.', 'u = (5, -1), v = (-2, 2). u - v = (5 - (-2), -1 - 2) = (7, -3).', 'Directed vectors between Cartesian points and vector subtraction.', 'Subtracting coordinates in reverse order (A - B instead of B - A).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Find the centroid (G) of the triangle with vertices A(0, 0), B(6, 0), and C(0, 4).', 'የሦስት ማዕዘን ጫፎች A(0, 0)፣ B(6, 0) እና C(0, 4) ቢሆኑ ሴንትሮይድ (G) ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 58) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('52808661-ab88-5455-912c-18d37215037f', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 'A', '(2, 4/3)', '(2, 4/3)', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('aa6ef631-4aa9-531d-a3a4-34ddee3fe719', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 'B', '(1, 2/3)', '(1, 2/3)', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c92194b6-77d9-56cd-a9f0-3489800d1d48', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 'C', '(9, 6/5)', '(9, 6/5)', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('77f2cd38-2724-59d1-8399-50cba3ebcd2f', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', 'D', '(6, 4/5)', '(6, 4/5)', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('3768e5f4-9c43-59e9-a965-2527f84c453a', '949c98bd-dd05-5fb2-aa29-f9b8ac8ca639', '1. Centroid formula for triangle with vertices (x₁,y₁), (x₂,y₂), (x₃,y₃):\nG = ((x₁ + x₂ + x₃)/3, (y₁ + y₂ + y₃)/3).\n2. x-coordinate: (0 + 6 + 0) / 3 = 6 / 3 = 2.\n3. y-coordinate: (0 + 0 + 4) / 3 = 4 / 3.\n4. Centroid G = (2, 4/3).\nTherefore, the correct answer is A.', 'G = ((0+6+0)/3, (0+0+4)/3) = (2, 4/3).', 'Triangle centroid coordinate formula.', 'Dividing by 2 (midpoint) instead of 3.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('454770a2-f2c3-5394-a437-dc0ba9e84ec6', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'The circle (x + 2)² + (y - 2)² = 1 is rotated counterclockwise by an angle of π/6 (30°) about the origin. What is the equation of the transformed image circle?', 'ክብ (x + 2)² + (y - 2)² = 1 ከመነሻ ነጥብ አንጻር በ π/6 (30°) በሰዓት ተቃራኒ አቅጣጫ ቢዞር አዲሱ የክቡ እኩልዮሽ ምን ይሆናል?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', 59) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7c16ffb2-45fe-5902-beee-6b3a81b81f97', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', 'A', '(x + (√3 - 1))² + (y - (√3 - 1))² = 1', '(x + (√3 - 1))² + (y - (√3 - 1))² = 1', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('6ebd378c-6c2a-5671-97f5-28116591f462', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', 'B', '(x - (√3 + 1))² + (y + (√3 - 1))² = 1', '(x - (√3 + 1))² + (y + (√3 - 1))² = 1', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('ba3bff81-34fa-5735-81c7-20dc518ef47e', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', 'C', '(x + (√3 + 1))² + (y - (√3 - 1))² = 1', '(x + (√3 + 1))² + (y - (√3 - 1))² = 1', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2d50a7a5-4033-5a1e-a645-f2f241140fd7', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', 'D', '(x - (√3 - 1))² + (y + (√3 + 1))² = 1', '(x - (√3 - 1))² + (y + (√3 + 1))² = 1', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('85aae35a-1aeb-5c37-aff6-c13cb6f105da', '454770a2-f2c3-5394-a437-dc0ba9e84ec6', '1. Original center of the circle is (h, k) = (-2, 2), with radius r = 1.\n2. Counterclockwise rotation formulas for angle θ = 30° (cos 30° = √3/2, sin 30° = 1/2):\n- h'' = h cos θ - k sin θ = -2(√3/2) - 2(1/2) = -√3 - 1 = -(√3 + 1)\n- k'' = h sin θ + k cos θ = -2(1/2) + 2(√3/2) = -1 + √3 = (√3 - 1)\n3. Equation of rotated circle centered at (h'', k''):\n(x - h'')² + (y - k'')² = 1 ⇒ (x - (-(√3 + 1)))² + (y - (√3 - 1))² = 1\n⇒ (x + (√3 + 1))² + (y - (√3 - 1))² = 1.\nTherefore, the correct answer is C.', 'New center is (-(√3+1), √3-1). Equation is (x + (√3+1))² + (y - (√3-1))² = 1.', 'Planar rotation of geometric curves around the origin.', 'Sign errors when plugging negative center coordinates into (x - h)².') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('f2910098-21b3-544a-ba8e-d8ba26f64b95', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Find the dot product (scalar product) of vectors u = i + 2j and v = -2i + 4j.', 'የቬክተሮች u = i + 2j እና v = -2i + 4j ዶት ፕሮዳክት (dot product) ስንት ነው?', 'easy', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', 60) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0aaa471f-5c9e-54fe-a4f6-89572a8bf863', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', 'A', '-8', '-8', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('492e122d-927c-5139-9924-7450bcbba922', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', 'B', '5', '5', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e7e2c73c-641e-5c07-bf17-55bf35ad08a3', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', 'C', '6', '6', true, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('19d56d3d-6f54-52df-9f36-50a2d156c09b', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', 'D', '7', '7', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('974d37c4-9032-5543-a3f7-515b2e992bf0', 'f2910098-21b3-544a-ba8e-d8ba26f64b95', '1. In components: u = (1, 2) and v = (-2, 4).\n2. Dot product: u · v = u_x v_x + u_y v_y = (1)(-2) + (2)(4) = -2 + 8 = 6.\nTherefore, the correct answer is C.', 'u · v = 1(-2) + 2(4) = -2 + 8 = 6.', 'Dot product of 2D orthogonal unit vectors: u · v = u₁ v₁ + u₂ v₂.', 'Arithmetic sign error: 8 - 2 = 6, not -8.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('6365c034-702e-5619-b7a3-e9da2a9cad45', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_2', 2014, 'Evaluate the indefinite integral: ∫ (x³ + x² - x) / (x² + x - 2) dx', 'የኢንቴግራል ስሌቱን ዋጋ ፈልጉ: ∫ (x³ + x² - x) / (x² + x - 2) dx', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '6365c034-702e-5619-b7a3-e9da2a9cad45', 61) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2e5cd545-2ca9-5c04-9d6b-e4cacece7489', '6365c034-702e-5619-b7a3-e9da2a9cad45', 'A', 'x²/2 + (1/3)ln|x - 1| + (2/3)ln|x + 2| + C', 'x²/2 + (1/3)ln|x - 1| + (2/3)ln|x + 2| + C', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('8a43f116-fea4-51b5-a17d-3cd6cc02f317', '6365c034-702e-5619-b7a3-e9da2a9cad45', 'B', 'x²/2 - (1/3)ln|x - 1| - (2/3)ln|x + 2| + C', 'x²/2 - (1/3)ln|x - 1| - (2/3)ln|x + 2| + C', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('7b7b291a-20c9-5b97-ad5f-9020bba0bc77', '6365c034-702e-5619-b7a3-e9da2a9cad45', 'C', 'x²/2 - (1/3)ln|x - 1| + (2/3)ln|x + 2| + C', 'x²/2 - (1/3)ln|x - 1| + (2/3)ln|x + 2| + C', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('c632fcf1-16c8-517e-8ecd-1b0391f41cce', '6365c034-702e-5619-b7a3-e9da2a9cad45', 'D', 'x²/2 + (1/3)ln|x - 1| - (2/3)ln|x + 2| + C', 'x²/2 + (1/3)ln|x - 1| - (2/3)ln|x + 2| + C', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('61717b33-2630-5acd-bff4-b6fba0519872', '6365c034-702e-5619-b7a3-e9da2a9cad45', '1. Polynomial long division:\n(x³ + x² - x) = x(x² + x - 2) + x ⇒ (x³ + x² - x)/(x² + x - 2) = x + x/(x² + x - 2).\n2. Factor denominator: x² + x - 2 = (x - 1)(x + 2).\n3. Partial fraction decomposition for x / [(x - 1)(x + 2)] = A/(x - 1) + B/(x + 2):\n- Multiply by (x - 1) at x = 1: A = 1 / (1 + 2) = 1/3\n- Multiply by (x + 2) at x = -2: B = -2 / (-2 - 1) = -2 / -3 = 2/3\n4. Integrate term by term:\n∫ [x + (1/3)/(x - 1) + (2/3)/(x + 2)] dx = x²/2 + (1/3)ln|x - 1| + (2/3)ln|x + 2| + C.\nTherefore, the correct answer is A.', 'Division gives x + partial fractions 1/[3(x-1)] + 2/[3(x+2)]. Integration yields x²/2 + (1/3)ln|x-1| + (2/3)ln|x+2| + C.', 'Integration of improper rational functions using polynomial division and partial fractions.', 'Skipping polynomial division when degree of numerator ≥ denominator.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'If r₁ and r₂ are the roots of the quadratic equation 3x² + 9x + 16 = 0, which equality is TRUE?', 'r₁ እና r₂ የኳድራቲክ እኩልዮሽ 3x² + 9x + 16 = 0 ሥሮች (roots) ቢሆኑ፣ ትክክል የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 62) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('fe2ed119-42ac-5984-be48-8a125206f283', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 'A', 'r₁ + r₂ = 3', 'r₁ + r₂ = 3', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1677995b-b0b6-5ba6-b3f4-765e6bb72901', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 'B', 'r₁ r₂ = -16/3', 'r₁ r₂ = -16/3', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('f61e1f48-c0fa-5c16-b85a-fe9dec0eb5c8', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 'C', 'r₁² + r₂² = 9/16', 'r₁² + r₂² = 9/16', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('fb1f0ca7-ad90-5133-87e2-89dd0ac42962', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', 'D', 'r₁² + r₂² = -5/3', 'r₁² + r₂² = -5/3', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('b45b5f8e-9af6-5da8-9443-851752970daf', '76f5c2a0-17d1-580e-95de-3ee1e2bcf548', '1. By Vieta''s formulas for ax² + bx + c = 0:\n- Sum of roots: r₁ + r₂ = -b / a = -9 / 3 = -3\n- Product of roots: r₁ r₂ = c / a = 16 / 3\n2. Identity for sum of squares: r₁² + r₂² = (r₁ + r₂)² - 2(r₁ r₂).\n3. Substitute values:\nr₁² + r₂² = (-3)² - 2(16/3) = 9 - 32/3 = 27/3 - 32/3 = -5/3.\nTherefore, the correct answer is D.', 'r₁ + r₂ = -3, r₁ r₂ = 16/3. r₁² + r₂² = (-3)² - 2(16/3) = 9 - 32/3 = -5/3.', 'Vieta''s formulas for polynomial roots.', 'Assuming r₁² + r₂² must be positive (roots are complex numbers with non-zero imaginary parts).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('37716e8c-1765-5b72-be6d-07a52ac36dff', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'The grouped frequency distribution gives marks out of 50: [20–25: 15], [26–31: 30], [32–37: 25], [38–43: 20], [44–49: 10]. Find the first quartile (Q₁).', 'ከ 50 የተሰጡ ውጤቶች ስርጭት: [20–25: 15]፣ [26–31: 30]፣ [32–37: 25]፣ [38–43: 20]፣ [44–49: 10] ቢሆን፣ የመጀመሪያው ኳርታይል (Q₁) ስንት ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '37716e8c-1765-5b72-be6d-07a52ac36dff', 63) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('08a90bf6-4034-5f3c-9b30-e5c0f4ae6c81', '37716e8c-1765-5b72-be6d-07a52ac36dff', 'A', '28.0', '28.0', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('0b02c6d9-f4b9-5a79-ae3b-bb1b9c8251c1', '37716e8c-1765-5b72-be6d-07a52ac36dff', 'B', '26.0', '26.0', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cd450862-dffd-5ff5-a025-6835838ebb82', '37716e8c-1765-5b72-be6d-07a52ac36dff', 'C', '26.5', '26.5', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('2cd4aded-4245-554a-b2b7-025648cc0d51', '37716e8c-1765-5b72-be6d-07a52ac36dff', 'D', '27.5', '27.5', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('912c4f54-dadc-5928-809e-0c67fdbaf261', '37716e8c-1765-5b72-be6d-07a52ac36dff', '1. Total frequency N = 15 + 30 + 25 + 20 + 10 = 100.\n2. First quartile position = N / 4 = 100 / 4 = 25th observation.\n3. Cumulative frequencies: Class 1 (20–25) = 15; Class 2 (26–31) = 45.\n4. Quartile class is 26–31, with lower boundary L = 25.5, class width h = 6, prior cumulative frequency cf = 15, class frequency f = 30.\n5. Q₁ = L + [(N/4 - cf) / f] · h = 25.5 + [(25 - 15) / 30] · 6 = 25.5 + (10/30) · 6 = 25.5 + 2.0 = 27.5.\nTherefore, the correct answer is D.', 'Q₁ = 25.5 + ((25 - 15) / 30) × 6 = 25.5 + 2 = 27.5.', 'Grouped data quartile interpolation formula: Q₁ = L + [(N/4 - cf)/f] h.', 'Using integer class limit (26) instead of exact continuous class boundary (25.5).') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 12, 'natural', 'math_g12', 'math_u1', 'math_t1_1', 2014, 'Let p and q be propositional statements. Which compound statement is a TAUTOLOGY (always true)?', 'p እና q የፕሮፖዚሽን አረፍተ ነገሮች ቢሆኑ፣ ቶቶሎጂ (ሁልጊዜ እውነት) የሆነው የቱ ነው?', 'medium', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 64) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('d4b1918c-0f28-5e72-850e-c2e977c098dc', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 'A', '(p ∨ q) ↔ p', '(p ∨ q) ↔ p', false, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('1f95d01d-9018-5c8a-9cbd-f43f6715afe1', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 'B', '(p ⇒ q) ↔ p', '(p ⇒ q) ↔ p', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('45789964-c196-52db-a74f-37b52058415a', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 'C', '(p ∧ q) ↔ p', '(p ∧ q) ↔ p', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('e222d313-eead-5d79-8a55-22dd4fdd4a9e', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', 'D', '(p ⇒ q) ↔ (¬p ∨ q)', '(p ⇒ q) ↔ (¬p ∨ q)', true, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('72ef0d22-c453-5565-bcd0-d4f89a2da4bf', '1b6eff0d-775f-53a8-9a40-f2efe2e8ae72', '1. By the fundamental Conditional-Disjunction equivalence rule, the implication (p ⇒ q) is logically equivalent to (¬p ∨ q).\n2. Because both sides have identical truth values in every possible truth assignment (T/T, T/F, F/T, F/F), their biconditional (A ↔ B) is TRUE in all cases.\n3. A statement that is true in every row of its truth table is a Tautology.\nTherefore, the correct answer is D.', '(p ⇒ q) is identically equivalent to (¬p ∨ q), making their biconditional always true (tautology).', 'Logical equivalences and tautologies.', 'Confusing material implication equivalence with conjunction.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
INSERT INTO public.questions (id, grade, stream, subject_id, unit_id, topic_id, exam_year, question_text_en, question_text_am, difficulty, verification_status, package_id) VALUES ('bf5c4b39-09e5-5f3f-8295-3991c2fef185', 12, 'natural', 'math_g12', 'math_u2', 'math_t2_1', 2014, 'Which statement is NOT TRUE about the graph of the rational function f(x) = 5 + |x| / (x + 1)?', 'ስለ ፈንክሽን f(x) = 5 + |x| / (x + 1) ግራፍ እውነት ያልሆነው የትኛው ነው?', 'hard', 'published', 'pkg_g12_math_nat_2014') ON CONFLICT (id) DO UPDATE SET question_text_en=EXCLUDED.question_text_en;
INSERT INTO public.exam_questions (exam_id, question_id, order_index) VALUES ('28826d5f-cd61-57cd-bcae-c044f8b36423', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', 65) ON CONFLICT (exam_id, question_id) DO NOTHING;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('b774f4da-ecb5-57da-a937-f8db1e6f8290', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', 'A', 'y = 5 + x is an oblique asymptote of the graph', 'y = 5 + x የግራፉ ኦብሊክ አስምፕቶት ነው', true, 1) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('17bbd65e-e3c6-5397-ab40-91169ce82a40', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', 'B', 'y = 6 is a horizontal asymptote as x → +∞', 'x → +∞ ሲሆን y = 6 አግድም አስምፕቶት ነው', false, 2) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('cb32a41f-4982-56d3-8f06-bf7f5b9cd812', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', 'C', 'y = 4 is a horizontal asymptote as x → -∞', 'x → -∞ ሲሆን y = 4 አግድም አስምፕቶት ነው', false, 3) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.answer_choices (id, question_id, choice_label, choice_text_en, choice_text_am, is_correct, sort_order) VALUES ('017a82d0-4540-582b-8f2f-4a0dfa6044be', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', 'D', 'x = -1 is a vertical asymptote of the graph', 'x = -1 የግራፉ ቋሚ አስምፕቶት ነው', false, 4) ON CONFLICT (id) DO UPDATE SET is_correct=EXCLUDED.is_correct;
INSERT INTO public.explanations (id, question_id, solution_text_en, simpler_explanation_en, key_concept_or_formula, common_pitfall) VALUES ('8d32f8da-1ce9-50ed-9f26-1588cd00291a', 'bf5c4b39-09e5-5f3f-8295-3991c2fef185', '1. For x > 0: |x| = x, so f(x) = 5 + x/(x+1) = 5 + 1 - 1/(x+1) = 6 - 1/(x+1). As x → +∞, f(x) → 6, so y = 6 is a horizontal asymptote (Statement B is true).\n2. For x < 0 (x ≠ -1): |x| = -x, so f(x) = 5 - x/(x+1) = 5 - [1 - 1/(x+1)] = 4 + 1/(x+1). As x → -∞, f(x) → 4, so y = 4 is a horizontal asymptote (Statement C is true).\n3. At x = -1, the denominator vanishes while the numerator is 1 ≠ 0, giving a vertical asymptote at x = -1 (Statement D is true).\n4. Since both horizontal asymptotes exist as x → ±∞, there is NO oblique asymptote.\nTherefore, statement A is NOT TRUE.', 'As x → +∞ the graph approaches y = 6, and as x → -∞ it approaches y = 4. There is no slant/oblique asymptote y = 5 + x.', 'Horizontal, vertical, and oblique asymptotes of piecewise rational functions.', 'Failing to split |x| into cases for x > 0 and x < 0.') ON CONFLICT (id) DO UPDATE SET solution_text_en=EXCLUDED.solution_text_en;
